window.BENTO_RECIPE_LIBRARY=[{"id":"jp_001","title":"Oyakodon","japaneseName":"親子丼","romanization":"oyakodon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small skillet or donburi pan","ingredients":["300 g cooked Japanese short-grain rice","250 g boneless chicken thigh, cut into bite-size pieces","1/2 medium onion, thinly sliced","3 large eggs, lightly beaten","160 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","2 tbsp mitsuba or sliced scallion, optional"],"steps":["Cook the rice first and keep it hot. Cut the chicken into similar-size pieces so it cooks evenly; slice the onion and lightly beat the eggs without fully homogenizing them.","Combine dashi, soy sauce, mirin, and sugar in a small skillet or donburi pan. Add the onion and bring to a gentle simmer for 2–3 minutes.","Add the chicken in a single layer. Simmer over medium-low heat for about 5–7 minutes, turning once, until the chicken is cooked through and the onion is tender.","Pour about two-thirds of the beaten egg evenly over the chicken. Cover and cook gently for about 45–60 seconds, until mostly set.","Add the remaining egg and mitsuba or scallion. Cover again for 20–40 seconds; the egg should be softly set rather than dry. Use pasteurized eggs if you prefer a very soft finish.","Divide hot rice between bowls and slide the chicken-and-egg mixture over the top with its cooking juices. Serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Oyakodon 親子丼 Japanese food","Oyakodon Japanese food"],"origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_002","title":"Gyudon","japaneseName":"牛丼","romanization":"gyudon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":18,"total":28,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["300 g cooked Japanese short-grain rice","250 g thinly sliced beef","1/2 medium onion, thinly sliced","180 ml dashi or water","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","pickled red ginger, optional","2 soft-cooked or pasteurized eggs, optional"],"steps":["Keep the cooked rice hot. Separate the beef slices so they do not clump and slice the onion thinly.","Add dashi, soy sauce, mirin, sake, and sugar to a skillet. Bring to a gentle simmer, then add the onion and cook for 4–5 minutes until softened.","Add the beef in loose layers. Simmer 3–5 minutes, skimming any foam, until the beef is just cooked and tender; avoid boiling hard because thin beef toughens quickly.","Taste the broth and reduce for another minute if it is too thin. It should be savory-sweet and still spoonable.","Divide rice between bowls, arrange the beef and onion on top, and spoon over enough broth to season the rice without flooding it.","Finish with pickled ginger and, if desired, a safely handled soft-cooked or pasteurized egg."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Gyudon 牛丼 Japanese food","Gyudon Japanese food"],"origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_003","title":"Katsudon","japaneseName":"カツ丼","romanization":"katsudon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"frying pan and small skillet","ingredients":["300 g cooked Japanese short-grain rice","2 boneless pork loin cutlets, about 120 g each","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten, for breading","60 g panko breadcrumbs","neutral oil for frying, as needed","1/2 onion, thinly sliced","160 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","2 eggs, lightly beaten","mitsuba or scallion, optional"],"steps":["Pat the pork dry, lightly season, and pound to an even thickness if needed.","Coat in flour, then beaten egg, then panko, pressing gently so the crumbs adhere.","Heat 2–3 cm of oil to about 170°C. Fry the pork until golden and cooked through, roughly 3–4 minutes per side depending on thickness. Drain on a rack and rest for 3 minutes.","Slice each tonkatsu into strips while keeping the cutlet together.","In a clean skillet, simmer dashi, soy sauce, mirin, sugar, and onion for 4–5 minutes until the onion softens.","Place the sliced cutlet over the onions. Pour the beaten eggs around and partly over the cutlet; cover and cook on low for 45–90 seconds until softly set.","Place hot rice in bowls and carefully slide the katsudon topping over each bowl. Garnish with mitsuba or scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Katsudon カツ丼 Japanese food","Katsudon Japanese food"],"origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_004","title":"Tendon","japaneseName":"天丼","romanization":"tendon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["300 g cooked Japanese short-grain rice","4 medium shrimp, peeled and deveined","4 thin slices kabocha squash","4 green beans","4 slices eggplant","70 g cake flour or all-purpose flour","1 small egg","120 ml ice-cold water","neutral oil for deep-frying, as needed","120 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar"],"steps":["Prepare the tempura sauce first: simmer dashi, soy sauce, mirin, and sugar for 2–3 minutes, then keep warm.","Dry the shrimp and vegetables thoroughly. Make shallow cuts on the underside of the shrimp and gently straighten them to reduce curling.","Heat frying oil to about 170–175°C.","Mix the egg with ice-cold water, then add flour and stir only a few strokes; lumps are desirable and overmixing makes the batter heavy.","Lightly dust the ingredients with flour if needed, dip in batter, and fry in small batches until crisp and just cooked. Drain on a rack, not paper towels, to preserve crispness.","Dip or lightly brush each piece of hot tempura with the warm tendon sauce.","Divide rice between bowls, arrange the tempura on top, and spoon over a little more sauce. Serve immediately so the coating stays crisp."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","shellfish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Tendon 天丼 Japanese food","Tendon Japanese food"],"origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_005","title":"Soboro Don","japaneseName":"そぼろ丼","romanization":"soboro don","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":12,"cook":18,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 skillets","ingredients":["300 g cooked Japanese short-grain rice","250 g ground chicken","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","3 eggs","1 tbsp sugar for eggs","pinch of salt","60 g blanched green beans or spinach, finely cut"],"steps":["Keep the rice hot. Mix ground chicken with soy sauce, mirin, sake, and sugar in a cold skillet before turning on the heat; this helps create fine crumbles.","Cook over medium heat, stirring continuously and breaking the chicken into small grains, until the liquid is mostly absorbed and the chicken is fully cooked, about 7–9 minutes.","Beat the eggs with sugar and a pinch of salt. Cook in a clean nonstick skillet over low-medium heat, stirring constantly with chopsticks or a spatula to make small, soft curds.","Season and finely chop the blanched green beans or spinach.","Divide rice between bowls. Arrange the chicken soboro, egg soboro, and green vegetable in separate sections over the rice.","Serve warm; the contrasting colors and textures are part of the classic presentation."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Soboro Don そぼろ丼 Japanese food","Soboro Don Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_006","title":"Unadon","japaneseName":"鰻丼","romanization":"unadon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":22,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan and broiler or skillet","ingredients":["300 g cooked Japanese short-grain rice","2 cooked unagi kabayaki fillets, about 100–120 g each","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","sansho pepper, optional"],"steps":["If using packaged cooked unagi, gently wipe away excess thick sauce if it is overly sweet, then pat dry.","Combine soy sauce, mirin, sake, and sugar in a small saucepan. Simmer 3–4 minutes until glossy but still fluid.","Warm the unagi under a broiler or in a covered skillet over low heat until heated through. Brush with the sauce during the final minute; avoid overcooking because eel dries quickly.","Divide hot rice between bowls and spoon a small amount of sauce over the rice.","Place the glazed eel on top and brush with a final thin layer of sauce.","Serve immediately with sansho pepper if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Unadon 鰻丼 Japanese food","Unadon Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_007","title":"Takikomi Gohan","japaneseName":"炊き込みご飯","romanization":"takikomi gohan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":40,"total":60,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker or heavy pot","ingredients":["2 rice-cooker cups Japanese short-grain rice, about 300 g","150 g boneless chicken thigh, small pieces","1 small carrot, cut into thin matchsticks","80 g shiitake mushrooms, sliced","60 g gobo, thinly shaved, optional","1 piece aburaage, blanched and sliced","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","dashi, enough to reach the rice-cooker 2-cup line","2 tbsp mitsuba or scallion"],"steps":["Rinse the rice until the water is mostly clear, then drain for about 15 minutes.","Prepare the chicken and vegetables in small pieces so they cook at the same rate as the rice. Briefly soak shaved gobo in water and drain.","Put the drained rice in the rice cooker.","Add soy sauce, mirin, and sake, then add dashi to the normal 2-cup water line and stir once.","Spread chicken, carrot, mushrooms, gobo, and aburaage evenly over the rice. Do not stir them deeply into the rice, which can cause uneven cooking.","Cook on the regular white-rice setting. When finished, rest unopened for 10 minutes.","Open, gently fold the toppings through the rice from the bottom, and garnish with mitsuba or scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Takikomi Gohan 炊き込みご飯 Japanese food","Takikomi Gohan Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_008","title":"Onigiri","japaneseName":"おにぎり","romanization":"onigiri","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":5,"total":20,"servings":6,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker","ingredients":["600 g freshly cooked Japanese short-grain rice","1/2 tsp fine salt","2 sheets nori, cut into strips","3 tbsp flaked salted salmon, optional filling","2 tbsp umeboshi flesh, optional filling","2 tbsp tuna mixed with 1 tbsp Japanese mayonnaise, optional filling"],"steps":["Prepare fillings before handling the rice. Use fillings that are cooked, pickled, or otherwise safe for room-temperature handling if the onigiri will be packed.","Let freshly cooked rice cool just enough to handle while it is still warm; cold rice is harder to shape and does not bind as well.","Wet clean hands with water and rub a tiny pinch of salt over the palms, or use a clean sheet of plastic wrap for shaping.","Place about 90–100 g rice in one hand, make a small hollow, add 1–2 teaspoons filling, then cover with rice.","Press gently into a triangle or round shape, rotating as you press. Do not compact so firmly that the grains become mashed.","Wrap with nori just before serving for crisp nori, or earlier if you prefer it soft. Cool promptly before packing into a closed lunch container."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Onigiri おにぎり Japanese food","Onigiri Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_009","title":"Omurice","japaneseName":"オムライス","romanization":"omuraisu","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["300 g cooked Japanese short-grain rice, preferably cooled","150 g boneless chicken thigh, diced","1/2 onion, diced","60 g green peas","3 tbsp ketchup, plus more to serve","1 tsp Worcestershire sauce","1 tbsp butter or neutral oil","4 large eggs","2 tbsp milk","pinch of salt","1 tsp butter for eggs"],"steps":["Dice the chicken and onion small. Break up any clumps in the cooked rice before starting.","Heat butter or oil in a skillet over medium heat. Cook chicken until no longer pink, then add onion and cook until softened.","Add rice and stir-fry until hot. Stir in ketchup and Worcestershire sauce and cook for another minute so the ketchup loses its raw taste. Fold in peas, then shape the rice into two oval mounds on plates.","For each omelet, beat 2 eggs with 1 tablespoon milk and a pinch of salt. Melt a little butter in a nonstick pan over medium-low heat.","Pour in the eggs and stir briefly to create fine curds, then stop stirring and let the base set while the top remains softly moist.","Slide or drape the omelet over the ketchup rice. Finish with a thin line of ketchup and serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","milk","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Omurice オムライス Japanese food","Omurice Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_010","title":"Ochazuke","japaneseName":"お茶漬け","romanization":"ochazuke","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":8,"cook":5,"total":13,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"kettle or saucepan","ingredients":["300 g hot cooked Japanese short-grain rice","350 ml hot green tea or light dashi","80 g cooked salted salmon, flaked","1 tbsp sliced scallion","1/2 sheet nori, shredded","1 tsp toasted sesame seeds","2 tsp arare rice crackers, optional","wasabi, optional"],"steps":["Place hot rice in two bowls, keeping the surface loose rather than packed.","Arrange flaked salmon, scallion, nori, sesame, and arare over the rice.","Heat green tea or light dashi until steaming but not aggressively boiling.","Pour the hot liquid around and over the toppings immediately before eating.","Add a small dab of wasabi if desired and eat while hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Ochazuke お茶漬け Japanese food","Ochazuke Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_011","title":"Shoyu Ramen","japaneseName":"醤油ラーメン","romanization":"shoyu ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":70,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 saucepans","ingredients":["2 portions fresh ramen noodles","700 ml chicken stock","10 g kombu","10 g dried shiitake mushrooms","3 tbsp soy sauce","1 tbsp mirin","1 tbsp sake","1 tsp sugar","1 tsp sesame oil","2 soft-boiled eggs","4 slices chashu or cooked pork","2 tbsp sliced scallion","nori and menma, optional"],"steps":["Soak kombu and dried shiitake in the chicken stock for 20 minutes.","Warm slowly, remove kombu just before a full boil, then simmer the shiitake for 10 minutes and strain.","For the tare, simmer soy sauce, mirin, sake, and sugar for 1–2 minutes. Divide the tare and sesame oil between two warmed ramen bowls.","Heat the finished broth until very hot and prepare toppings before cooking the noodles; ramen should be assembled immediately.","Boil fresh ramen noodles according to the package, usually 1–3 minutes. Stir to separate, then drain extremely well.","Pour hot broth into each bowl and stir with the tare. Add noodles, lifting once to loosen them.","Top with egg, chashu, scallion, nori, and menma. Serve at once."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Shoyu Ramen 醤油ラーメン Japanese food","Shoyu Ramen Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_012","title":"Miso Ramen","japaneseName":"味噌ラーメン","romanization":"miso ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":55,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan and noodle pot","ingredients":["2 portions fresh ramen noodles","700 ml chicken or pork stock","3 tbsp red or awase miso","1 tbsp soy sauce","1 tbsp sake","1 tsp sugar","1 tsp grated ginger","1 clove garlic, grated","150 g ground pork","1 tsp sesame oil","100 g bean sprouts","80 g corn kernels","2 tbsp sliced scallion","2 soft-boiled eggs, optional"],"steps":["Mix miso, soy sauce, sake, sugar, ginger, and garlic into a smooth seasoning paste.","Heat sesame oil in a saucepan and cook the ground pork over medium-high heat until browned and fully cooked.","Add the seasoning paste and stir for about 30 seconds, then gradually add stock while stirring so the miso disperses evenly.","Do not boil hard for a long time after adding miso.","Add bean sprouts and corn and simmer just until hot and crisp-tender. Keep the soup very hot.","Cook ramen noodles separately according to package directions and drain well.","Divide noodles between bowls, ladle over the miso broth and pork, then top with scallion and egg if using."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","sesame","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Miso Ramen 味噌ラーメン Japanese food","Miso Ramen Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_013","title":"Tonkotsu Ramen","japaneseName":"豚骨ラーメン","romanization":"tonkotsu ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":360,"total":405,"servings":4,"difficulty":"Hard","energy":"high","cleanup":3,"freezer":"no","equipment":"large stockpot","ingredients":["1.5 kg pork femur and neck bones","3 L water, plus more for blanching","1 onion, halved","1 head garlic, halved","30 g ginger, sliced","4 portions thin ramen noodles","4 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tsp salt, plus more to taste","8 slices chashu","4 ramen eggs","4 tbsp sliced scallion","pickled ginger and sesame seeds, optional"],"steps":["Rinse the bones, cover with cold water, bring to a hard boil for 10 minutes, then drain. Scrub away dark blood or scum from the bones and wash the pot; this keeps the broth cleaner-tasting.","Return the cleaned bones to the pot with 3 L fresh water.","Bring to a vigorous boil and maintain an active boil for about 5–6 hours, topping up with hot water as needed to keep the bones mostly submerged.","After the first hour, add onion, garlic, and ginger. Stir and break up the bones occasionally; agitation helps emulsify fat and collagen into the characteristic opaque broth.","Strain the broth through a sturdy fine sieve. Skim only excess surface fat, then season lightly with salt.","Make a simple shoyu tare by simmering soy sauce, mirin, and sake for 1–2 minutes.","Put about 1 tablespoon tare in each warmed bowl.","Cook thin ramen noodles just until firm, drain thoroughly, and add to bowls. Ladle in boiling-hot tonkotsu broth, then add chashu, ramen egg, scallion, pickled ginger, and sesame."],"notes":"Traditional tonkotsu broth is a long, vigorous pork-bone boil. This home version preserves that technique; use good ventilation and maintain food-safe handling of the bones.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Tonkotsu Ramen 豚骨ラーメン Japanese food","Tonkotsu Ramen Japanese food"],"origin":"Fukuoka / Kyushu","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Fukuoka / Kyushu","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_014","title":"Kitsune Udon","japaneseName":"きつねうどん","romanization":"kitsune udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 saucepans","ingredients":["2 portions udon noodles","700 ml dashi","2 tbsp light soy sauce or regular soy sauce","2 tbsp mirin","1/2 tsp salt","2 pieces aburaage fried tofu","150 ml dashi for tofu","1 tbsp soy sauce for tofu","1 tbsp sugar for tofu","1 tbsp mirin for tofu","2 tbsp sliced scallion"],"steps":["Blanch the aburaage in boiling water for 1 minute to remove excess surface oil, then gently squeeze dry.","Simmer the aburaage with 150 ml dashi, soy sauce, sugar, and mirin for 8–10 minutes until the liquid is mostly absorbed. Set aside.","For the udon broth, heat 700 ml dashi with soy sauce, mirin, and salt. Keep at a gentle simmer and adjust seasoning to a clean, savory balance.","Cook or warm the udon according to package directions. Drain well.","Divide noodles between bowls and pour over the hot broth.","Top each bowl with seasoned aburaage and scallion. Serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Kitsune Udon きつねうどん Japanese food","Kitsune Udon Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_015","title":"Curry Udon","japaneseName":"カレーうどん","romanization":"kare udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":25,"total":40,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["2 portions udon noodles","150 g thinly sliced pork or beef","1/2 onion, sliced","700 ml dashi","2 tbsp soy sauce","2 tbsp mirin","2 blocks Japanese curry roux, about 40 g","1 tbsp potato starch mixed with 1 tbsp water, optional","2 tbsp sliced scallion"],"steps":["Bring dashi, soy sauce, and mirin to a simmer. Add onion and cook for 4–5 minutes until softened.","Add the thinly sliced meat and simmer gently until fully cooked, skimming any foam.","Turn the heat low. Add curry roux a little at a time, stirring until completely dissolved. Do not add roux to a violently boiling pot.","If you want a thicker noodle broth, stir in the potato-starch slurry and simmer for 30–60 seconds until glossy.","Cook or warm udon separately, drain, and divide between bowls.","Ladle the curry broth and meat over the udon, finish with scallion, and serve very hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Curry Udon カレーうどん Japanese food","Curry Udon Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_016","title":"Nabeyaki Udon","japaneseName":"鍋焼きうどん","romanization":"nabeyaki udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 small heatproof pots","ingredients":["2 portions udon noodles","800 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tsp salt","150 g chicken thigh, bite-size pieces","4 shiitake mushrooms","4 slices kamaboko fish cake","2 eggs","2 shrimp tempura, optional","2 tbsp sliced scallion","handful of spinach, blanched"],"steps":["Prepare all toppings before cooking because nabeyaki udon is assembled quickly in individual pots.","Heat dashi with soy sauce, mirin, and salt. Add chicken and shiitake and simmer 5–7 minutes until the chicken is cooked through.","Divide the broth, chicken, and mushrooms between two small heatproof pots. Add udon and bring each pot back to a gentle simmer.","Arrange kamaboko and spinach around the noodles.","Crack one egg into each pot without breaking the yolk.","Cover and simmer 2–4 minutes depending on how set you prefer the egg. Use pasteurized eggs if serving the yolk very soft.","Add shrimp tempura at the end so it keeps some crispness, scatter with scallion, and serve in the cooking pot with care."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","fish","shellfish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Nabeyaki Udon 鍋焼きうどん Japanese food","Nabeyaki Udon Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_017","title":"Zaru Soba","japaneseName":"ざるそば","romanization":"zaru soba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":10,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan and noodle pot","ingredients":["200 g dried soba noodles","200 ml water","100 ml soy sauce","30 ml mirin","20 g sugar","15 g katsuobushi bonito flakes","1 small scallion, finely sliced","wasabi, to taste","1/2 sheet nori, shredded"],"steps":["Make the dipping sauce: boil water, sugar, mirin, and soy sauce briefly. Add bonito flakes, return just to a boil, turn off the heat, cool, then strain. Chill the sauce.","Bring a large pot of unsalted water to a rolling boil and cook soba according to the package, stirring gently so the strands do not stick.","Drain immediately and rinse thoroughly under cold running water, gently rubbing and swishing the noodles to remove surface starch.","Cool the noodles completely in cold water, then drain very well.","Arrange soba on a tray or plate and top with shredded nori. Divide chilled dipping sauce into small cups.","Serve with scallion and wasabi. Dip only a portion of the noodles into the sauce before eating."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Zaru Soba ざるそば Japanese food","Zaru Soba Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_018","title":"Yakisoba","japaneseName":"焼きそば","romanization":"yakisoba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":15,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large skillet or griddle","ingredients":["2 portions steamed yakisoba noodles","150 g thinly sliced pork belly","120 g cabbage, chopped","1/2 carrot, thinly sliced","1/2 onion, sliced","1 tbsp neutral oil","2 tbsp Japanese Worcestershire-style sauce","1 tbsp oyster sauce","1 tsp soy sauce","aonori and pickled ginger, optional"],"steps":["Loosen the noodles according to package directions. If tightly packed, rinse briefly with warm water and drain thoroughly.","Heat oil in a large skillet or griddle over medium-high heat. Cook pork until nearly done and lightly browned.","Add onion and carrot and stir-fry 2 minutes, then add cabbage and cook until just tender but still crisp.","Add noodles. Let them contact the hot pan for 30–60 seconds before tossing so they pick up light browning.","Add Worcestershire-style sauce, oyster sauce, and soy sauce around the edge of the pan. Toss until the noodles are evenly seasoned and the pork is fully cooked.","Serve immediately with aonori and pickled ginger if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","shellfish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Yakisoba 焼きそば Japanese food","Yakisoba Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_019","title":"Yaki Udon","japaneseName":"焼きうどん","romanization":"yaki udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":15,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large skillet","ingredients":["2 portions udon noodles","150 g thinly sliced pork","120 g cabbage, chopped","1/2 onion, sliced","1/2 carrot, thinly sliced","1 tbsp neutral oil","1 1/2 tbsp soy sauce","1 tbsp mirin","1 tsp Worcestershire sauce","2 tbsp katsuobushi, optional","2 tbsp sliced scallion"],"steps":["Cook or loosen udon according to package instructions, then drain very well.","Heat oil in a large skillet over medium-high heat. Cook pork until almost done.","Add onion and carrot and stir-fry 2 minutes, then add cabbage and cook another 1–2 minutes.","Add drained udon and toss gently so the noodles do not break. Let them sear briefly where they contact the pan.","Add soy sauce, mirin, and Worcestershire sauce; toss until evenly coated and the pork is fully cooked.","Finish with scallion and katsuobushi if using. Serve hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Yaki Udon 焼きうどん Japanese food","Yaki Udon Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_020","title":"Hiyashi Chuka","japaneseName":"冷やし中華","romanization":"hiyashi chuka","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":10,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet and noodle pot","ingredients":["2 portions fresh ramen noodles","2 eggs","1 tsp neutral oil","1/2 cucumber, julienned","1 small tomato, cut into wedges","80 g ham, julienned","60 g cooked shrimp, optional","3 tbsp soy sauce","3 tbsp rice vinegar","2 tbsp sugar","1 tbsp sesame oil","2 tbsp water","1 tsp grated ginger"],"steps":["Whisk the eggs. Cook as a thin omelet in a lightly oiled skillet, cool, then slice into fine strips.","Prepare cucumber, tomato, ham, and shrimp and keep chilled.","Whisk soy sauce, rice vinegar, sugar, sesame oil, water, and ginger until the sugar dissolves. Chill the dressing.","Boil ramen noodles according to package directions. Drain and rinse thoroughly under cold water until completely cool, then drain very well.","Divide noodles between shallow bowls. Arrange the toppings in neat sections over the noodles.","Spoon the chilled dressing over just before serving and toss at the table."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","sesame","shellfish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Hiyashi Chuka 冷やし中華 Japanese food","Hiyashi Chuka Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_021","title":"Chicken Teriyaki","japaneseName":"鶏の照り焼き","romanization":"tori no teriyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":18,"total":28,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["2 boneless skin-on chicken thighs, about 300 g total","1 tsp neutral oil","2 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 tbsp sugar"],"steps":["Pat the chicken dry and trim excess fat. Prick the skin in several places so it renders evenly.","Mix soy sauce, mirin, sake, and sugar until the sugar starts to dissolve.","Heat oil in a skillet over medium heat. Place chicken skin-side down and press lightly for the first minute. Cook 5–7 minutes until deeply golden, spooning off excess rendered fat.","Turn the chicken and cook 3–5 minutes until almost cooked through.","Lower the heat, add the teriyaki mixture, and simmer while turning the chicken repeatedly until the sauce becomes glossy and coats the meat.","Rest 2 minutes, slice, and spoon the remaining glaze over the chicken."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chicken Teriyaki 鶏の照り焼き Japanese food","Chicken Teriyaki Japanese food"],"origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_022","title":"Chicken Karaage","japaneseName":"鶏の唐揚げ","romanization":"tori no karaage","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["600 g boneless chicken thighs, bite-size pieces","2 tbsp soy sauce","1 tbsp sake","1 tbsp grated ginger","1 clove garlic, grated","70 g potato starch","30 g all-purpose flour","neutral oil for deep-frying, as needed","4 lemon wedges"],"steps":["Mix chicken with soy sauce, sake, ginger, and garlic. Marinate 20–30 minutes in the refrigerator, then drain off excess liquid.","Combine potato starch and flour. Coat each chicken piece thoroughly just before frying, pressing the starch into moist crevices.","Heat oil to about 170°C. Fry in batches for 3–4 minutes until pale golden and cooked almost through. Do not crowd the pot.","Transfer to a rack and rest 3 minutes; this pause lets residual heat move through the meat.","Increase the oil to about 185°C and fry the chicken a second time for 45–75 seconds until crisp and deep golden.","Drain on a rack, season lightly if needed, and serve hot with lemon."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chicken Karaage 鶏の唐揚げ Japanese food","Chicken Karaage Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_023","title":"Chicken Nanban","japaneseName":"チキン南蛮","romanization":"chikin nanban","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet and small saucepan","ingredients":["2 boneless chicken thighs, about 320 g","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten","neutral oil for shallow-frying, as needed","2 tbsp soy sauce","2 tbsp rice vinegar","2 tbsp sugar","1 tbsp mirin","2 hard-boiled eggs, chopped","3 tbsp Japanese mayonnaise","1 tbsp finely chopped onion","1 tbsp chopped pickles or cucumber","1 tsp lemon juice"],"steps":["Make the tartar sauce by mixing chopped egg, mayonnaise, onion, pickle, and lemon.","Chill while you cook the chicken.","Combine soy sauce, rice vinegar, sugar, and mirin in a small pan and warm just until the sugar dissolves; keep the nanban sauce warm.","Season chicken lightly, coat with flour, then dip in beaten egg.","Shallow-fry over medium heat until golden on both sides and fully cooked, about 5–7 minutes per side depending on thickness.","While the chicken is still hot, place it in the warm nanban sauce and turn several times so the coating absorbs the sweet-sour seasoning.","Slice and serve with plenty of tartar sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chicken Nanban チキン南蛮 Japanese food","Chicken Nanban Japanese food"],"origin":"Miyazaki","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Miyazaki","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_024","title":"Tonkatsu","japaneseName":"豚カツ","romanization":"tonkatsu","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep frying pot","ingredients":["2 pork loin cutlets, about 140 g each","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten","70 g panko breadcrumbs","neutral oil for deep-frying, as needed","120 g finely shredded cabbage","tonkatsu sauce, to serve"],"steps":["Cut small slits through the fat and connective tissue around the edge of each pork cutlet to reduce curling. Pound to an even thickness and season lightly.","Coat each cutlet in flour and shake off excess, dip in beaten egg, then press into panko without crushing the crumbs.","Heat oil to about 170°C. Lower in the cutlets carefully and fry until golden on the first side.","Turn once and continue frying until the center is safely cooked, usually 5–7 minutes total depending on thickness.","Drain upright on a rack and rest 3–5 minutes before slicing; resting helps keep the juices in the meat.","Slice into strips and serve with shredded cabbage and tonkatsu sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Tonkatsu 豚カツ Japanese food","Tonkatsu Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_025","title":"Shogayaki","japaneseName":"豚の生姜焼き","romanization":"buta no shogayaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":12,"total":27,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["300 g thinly sliced pork loin","1/2 onion, thinly sliced","1 tbsp neutral oil","2 tbsp soy sauce","2 tbsp sake","1 tbsp mirin","1 tbsp grated fresh ginger","1 tsp sugar","shredded cabbage, to serve"],"steps":["Mix soy sauce, sake, mirin, ginger, and sugar. Keep the pork slices loose rather than marinating them for a long time.","Heat oil in a skillet over medium-high heat. Cook the pork in batches for about 1 minute per side until lightly browned; remove before it dries out.","Add onion to the same pan and cook 2–3 minutes until softened.","Return pork to the pan and add the ginger sauce. Toss over medium heat for 1–2 minutes until the sauce reduces and coats the meat.","Check that the pork is fully cooked, then remove from heat immediately.","Serve with shredded cabbage and hot rice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Shogayaki 豚の生姜焼き Japanese food","Shogayaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_026","title":"Nikujaga","japaneseName":"肉じゃが","romanization":"nikujaga","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":55,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide pot","ingredients":["350 g thinly sliced beef or pork","600 g potatoes, peeled and cut into large chunks","1 onion, cut into wedges","1 carrot, cut into chunks","150 g shirataki noodles, rinsed and cut, optional","250 ml dashi","3 tbsp soy sauce","3 tbsp mirin","2 tbsp sake","2 tbsp sugar","1 tbsp neutral oil","80 g green beans, blanched"],"steps":["Rinse the shirataki well and briefly boil if the package recommends it.","Prepare potatoes, carrot, and onion in large pieces so they hold their shape.","Heat oil in a wide pot. Cook the meat briefly until most of the pink disappears, then add onion and carrot and stir for 2 minutes.","Add potatoes and shirataki. Pour in dashi, sugar, sake, and mirin and bring to a gentle boil.","Skim foam, then cover with a drop lid or parchment circle and simmer 12–15 minutes until the vegetables are nearly tender.","Add soy sauce and continue simmering uncovered or with the drop lid until potatoes are tender and the broth has reduced, about 8–10 minutes.","Rest 10 minutes off the heat so the flavors absorb, then rewarm gently and garnish with green beans."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Nikujaga 肉じゃが Japanese food","Nikujaga Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_027","title":"Hambagu","japaneseName":"ハンバーグ","romanization":"hanbagu","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["350 g ground beef","150 g ground pork","1 small onion, finely diced","1 tsp neutral oil","40 g panko","60 ml milk","1 egg","1/2 tsp salt","1/4 tsp black pepper","1 tbsp neutral oil for frying","3 tbsp ketchup","2 tbsp Worcestershire sauce","2 tbsp water","1 tsp butter"],"steps":["Cook the diced onion in 1 teaspoon oil over medium-low heat until translucent. Cool completely. Soak panko in milk for 5 minutes.","Mix beef, pork, cooled onion, soaked panko, egg, salt, and pepper. Knead just until sticky and cohesive; overmixing can make the patties dense.","Divide into four. Toss each portion between your hands to expel large air pockets, shape into oval patties, and press a shallow indentation in the center.","Heat oil in a skillet over medium heat. Brown patties 3–4 minutes on the first side, turn, add 2 tablespoons water, cover, and cook 6–8 minutes until safely cooked through.","Remove patties. Add ketchup, Worcestershire sauce, 2 tablespoons water, and butter to the pan; scrape up browned bits and simmer to a glossy sauce.","Serve the hambagu with the pan sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Hambagu ハンバーグ Japanese food","Hambagu Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_028","title":"Buta no Kakuni","japaneseName":"豚の角煮","romanization":"buta no kakuni","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":130,"total":150,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"heavy pot","ingredients":["800 g pork belly, cut into 5 cm cubes","30 g ginger, sliced","2 scallions, green parts reserved","700 ml water","100 ml sake","4 tbsp soy sauce","3 tbsp sugar","3 tbsp mirin","4 soft- or hard-boiled eggs, optional","blanched mustard greens, optional"],"steps":["Brown the pork belly cubes in a heavy pot over medium heat, starting fatty side down. Drain excess rendered fat.","Cover pork with fresh water, add half the ginger and scallion greens, and simmer gently for 60 minutes.","Drain and rinse the pork; discard the blanching liquid.","Return pork to the clean pot with 700 ml water, sake, remaining ginger, and sugar. Simmer gently 30 minutes.","Add soy sauce and mirin. Cover with a drop lid and simmer another 30–40 minutes until the pork is very tender.","If using cooked eggs, add them during the final 15 minutes and turn occasionally so they color evenly.","Let the pork rest in the braising liquid for at least 15 minutes; skim excess fat, rewarm gently, and serve with some reduced sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Buta no Kakuni 豚の角煮 Japanese food","Buta no Kakuni Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_029","title":"Saba no Misoni","japaneseName":"鯖の味噌煮","romanization":"saba no misoni","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide saucepan","ingredients":["2 mackerel fillets, about 150 g each","150 ml water","50 ml sake","2 tbsp mirin","1 tbsp sugar","2 tbsp miso","1 tbsp soy sauce","15 g ginger, thinly sliced"],"steps":["Check the mackerel for pin bones and cut each fillet in half. Make a shallow cross cut in the skin of thick pieces.","Pour boiling water briefly over the fish, then immediately rinse in cool water. This traditional pre-treatment helps remove surface odor and blood.","Bring water, sake, mirin, sugar, and ginger to a simmer in a wide pan. Add mackerel skin-side up.","Cover with a drop lid and simmer gently for about 8 minutes.","Dissolve miso with a little hot cooking liquid, then add it with soy sauce. Continue simmering 5–7 minutes, spooning sauce over the fish without breaking it.","When the fish is cooked and the sauce lightly thickened, rest for 2 minutes and serve with ginger and sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Saba no Misoni 鯖の味噌煮 Japanese food","Saba no Misoni Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_030","title":"Salmon Shioyaki","japaneseName":"鮭の塩焼き","romanization":"sake no shioyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":12,"total":47,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"grill, broiler, or grill pan","ingredients":["2 skin-on salmon fillets, 150–180 g each","1 tsp fine salt","grated daikon, optional","2 lemon or sudachi wedges"],"steps":["Pat salmon dry. Sprinkle salt evenly over both sides and refrigerate uncovered for 30 minutes; this seasons the fish and draws out surface moisture.","Pat the salmon dry again. Bring close to room temperature while preheating a grill, broiler, or grill pan.","Cook skin-side toward the stronger heat first until the skin is crisp and the fish is mostly opaque, about 5–7 minutes depending on thickness.","Turn and cook the second side just until the center is safely cooked and still moist, about 3–5 minutes.","Rest 2 minutes. Serve with grated daikon and citrus if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Salmon Shioyaki 鮭の塩焼き Japanese food","Salmon Shioyaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_031","title":"Saikyo Yaki Cod","japaneseName":"西京焼き","romanization":"saikyo yaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":12,"total":500,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"broiler or grill","ingredients":["2 cod or sablefish fillets, 150 g each","80 g white miso","2 tbsp mirin","2 tbsp sake","1 tbsp sugar"],"steps":["Mix white miso, mirin, sake, and sugar into a smooth marinade.","Pat the fish dry and coat all sides with the miso mixture. Refrigerate 6–8 hours; for delicate cod, avoid excessively long marination because salt can firm the flesh too much.","Remove fish from the marinade and wipe off most of the miso with your fingers or a damp paper towel; thick miso burns before the fish cooks.","Broil or grill over medium heat, starting skin-side down if present, until lightly caramelized.","Turn once if needed and cook until the center is opaque and flakes easily, about 8–12 minutes total depending on thickness.","Rest 2 minutes before serving."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Saikyo Yaki Cod 西京焼き Japanese food","Saikyo Yaki Cod Japanese food"],"origin":"Kyoto","profile":"Regional technique","seasonality":"All year","tags":["Regional technique","Kyoto","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_032","title":"Japanese Beef Curry","japaneseName":"ビーフカレー","romanization":"biifu karee","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":60,"total":80,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"heavy pot","ingredients":["500 g beef chuck, 3 cm cubes","1 large onion, sliced","2 carrots, large chunks","2 potatoes, large chunks","1 tbsp neutral oil","800 ml water or unsalted stock","100 g Japanese curry roux blocks","1 tsp grated apple or honey, optional","cooked Japanese rice, to serve"],"steps":["Pat beef dry. Heat oil in a heavy pot and brown the beef in batches; do not crowd the pot.","Add onion and cook 6–8 minutes until soft and lightly golden. Return all beef to the pot.","Add water or stock, bring to a boil, skim foam, then lower to a gentle simmer and cook 30 minutes.","Add carrots and potatoes and simmer 15–20 minutes until the beef and vegetables are tender.","Turn off the heat.","Break curry roux into pieces and dissolve them one at a time, stirring until smooth. Add grated apple or honey if using.","Return to low heat and simmer 5–10 minutes, stirring frequently so the thick curry does not catch. Serve beside hot rice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","milk"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Japanese Beef Curry ビーフカレー Japanese food","Japanese Beef Curry Japanese food"],"origin":"Japan","profile":"Popular yoshoku","seasonality":"All year","tags":["Popular yoshoku","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_033","title":"Assorted Tempura","japaneseName":"天ぷら","romanization":"tempura","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["6 medium shrimp","1 small Japanese eggplant","80 g kabocha squash","4 shiitake mushrooms","4 green beans","100 g all-purpose flour, plus extra for dusting","1 egg","200 ml ice-cold water","neutral oil for deep-frying, as needed","150 ml dashi","2 tbsp soy sauce","2 tbsp mirin","grated daikon and ginger, optional"],"steps":["Make tentsuyu by simmering dashi, soy sauce, and mirin for 2–3 minutes. Keep warm.","Prepare and thoroughly dry the shrimp and vegetables.","Make shallow cuts under the shrimp and gently straighten them; cut vegetables into pieces thin enough to cook quickly.","Heat oil to about 170°C. Keep batter ingredients cold until the last moment.","Beat egg into ice-cold water. Add flour and mix only a few strokes with chopsticks or a fork; leave visible lumps and do not develop gluten.","Dust ingredients lightly with flour, dip in batter, and fry in small batches. Vegetables generally take 2–3 minutes; shrimp about 2–3 minutes depending on size.","Drain on a rack and serve immediately with tentsuyu, grated daikon, and ginger."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","shellfish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Assorted Tempura 天ぷら Japanese food","Assorted Tempura Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_034","title":"Osaka-Style Okonomiyaki","japaneseName":"お好み焼き","romanization":"okonomiyaki","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"griddle or large skillet","ingredients":["120 g all-purpose flour","160 ml dashi","2 eggs","300 g cabbage, finely chopped","2 tbsp tenkasu tempura crumbs, optional","2 tbsp pickled red ginger, chopped","120 g thinly sliced pork belly","1 tbsp neutral oil","4 tbsp okonomiyaki sauce","2 tbsp Japanese mayonnaise","1 tsp aonori and 5 g katsuobushi"],"steps":["Whisk flour and dashi until just smooth. Stir in eggs, then fold in cabbage, tenkasu, and pickled ginger. Do not compress the cabbage.","Heat a lightly oiled griddle or skillet over medium heat. Divide the batter into two thick rounds about 15 cm wide.","Lay pork belly slices over the top of each pancake. Cook 4–5 minutes until the bottom is browned and stable enough to flip.","Flip carefully so the pork is now underneath.","Cook another 5–6 minutes, pressing only very lightly; excessive pressing makes the pancake dense.","Flip once more and cook 1–2 minutes until the center is fully set and the pork is cooked.","Brush with okonomiyaki sauce, drizzle mayonnaise, and finish with aonori and katsuobushi."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Osaka-Style Okonomiyaki お好み焼き Japanese food","Osaka-Style Okonomiyaki Japanese food"],"origin":"Osaka","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Osaka","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_035","title":"Takoyaki","japaneseName":"たこ焼き","romanization":"takoyaki","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"takoyaki pan","ingredients":["120 g all-purpose flour","400 ml dashi","2 eggs","1 tbsp soy sauce","150 g cooked octopus, 1.5 cm pieces","3 tbsp tenkasu","2 tbsp pickled red ginger, chopped","2 tbsp sliced scallion","1 tbsp neutral oil for the pan, plus more as needed","4 tbsp takoyaki sauce","2 tbsp Japanese mayonnaise","1 tsp aonori and 5 g katsuobushi"],"steps":["Whisk flour, dashi, eggs, and soy sauce into a thin batter. Transfer to a jug for easier pouring.","Heat a takoyaki pan over medium-high heat and oil every cavity generously, including the flat surface between holes.","Fill cavities nearly to the top with batter.","Add octopus, tenkasu, ginger, and scallion, then pour a little more batter so it spills slightly over the edges.","When the edges set, use skewers to cut the connecting batter and rotate each ball about 90 degrees, tucking loose batter underneath.","Continue turning repeatedly until the takoyaki are round, crisp outside, and cooked through, about 6–8 minutes total.","Transfer to a plate and finish with takoyaki sauce, mayonnaise, aonori, and katsuobushi."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy","mollusk","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Takoyaki たこ焼き Japanese food","Takoyaki Japanese food"],"origin":"Osaka","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Osaka","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_036","title":"Yakitori","japaneseName":"焼き鳥","romanization":"yakitori","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":15,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"grill or grill pan","ingredients":["600 g boneless chicken thigh","4 scallions, white and light-green parts","8 bamboo skewers, soaked","60 ml soy sauce","60 ml mirin","30 ml sake","1 1/2 tbsp sugar"],"steps":["Soak bamboo skewers in water for at least 20 minutes. Cut chicken into 2.5 cm pieces and scallion into 3 cm lengths.","Make tare by simmering soy sauce, mirin, sake, and sugar for 5–7 minutes until lightly syrupy. Reserve some clean sauce for serving.","Thread chicken and scallion alternately onto skewers without packing too tightly.","Grill over medium-high heat, turning every 1–2 minutes, until the chicken is nearly cooked and lightly charred.","Brush with tare during the final several turns, allowing each layer to caramelize before adding more.","Cook chicken fully, then brush with reserved clean tare and serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Yakitori 焼き鳥 Japanese food","Yakitori Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_037","title":"Japanese Gyoza","japaneseName":"餃子","romanization":"gyoza","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":15,"total":45,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["30 gyoza wrappers","300 g ground pork","200 g napa cabbage, finely chopped","1/2 tsp salt for cabbage","3 scallions, finely chopped","1 tbsp grated ginger","1 clove garlic, grated","1 tbsp soy sauce","1 tbsp sake","1 tsp sesame oil","1 tsp potato starch","1 tbsp neutral oil","80 ml water","2 tbsp rice vinegar plus 2 tbsp soy sauce, for dipping"],"steps":["Salt the chopped cabbage, rest 10 minutes, then squeeze out as much water as possible.","Mix pork, cabbage, scallion, ginger, garlic, soy sauce, sake, sesame oil, and potato starch until the filling becomes slightly sticky.","Place about 1 tablespoon filling in each wrapper.","Moisten the rim, fold, and pleat one side against the other; keep finished gyoza covered so wrappers do not dry.","Heat oil in a nonstick skillet. Arrange gyoza flat-side down and cook 1–2 minutes until the bottoms begin to color.","Add water, immediately cover, and steam 4–5 minutes until the filling is fully cooked.","Remove the lid and cook until the water evaporates and bottoms become crisp. Serve hot with vinegar-soy dipping sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Japanese Gyoza 餃子 Japanese food","Japanese Gyoza Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_038","title":"Korokke","japaneseName":"コロッケ","romanization":"korokke","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":20,"total":55,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"pot and deep fryer","ingredients":["700 g potatoes, peeled and quartered","200 g ground beef","1 small onion, finely diced","1 tsp neutral oil","1 tsp sugar","1 tbsp soy sauce","1/2 tsp salt and 1/4 tsp black pepper","60 g all-purpose flour","2 eggs, beaten","120 g panko","neutral oil for deep-frying, as needed"],"steps":["Boil potatoes in salted water until very tender. Drain thoroughly, return to the hot pot for 1 minute to steam off moisture, then mash while hot.","Cook onion in oil until soft. Add beef and cook until fully browned; season with sugar, soy sauce, salt, and pepper. Cook until excess moisture is gone.","Mix beef mixture into the mashed potatoes. Spread on a tray and cool until firm enough to handle.","Shape into 8 oval patties. Coat each in flour, beaten egg, then panko. Chill 15 minutes if the coating feels soft.","Heat oil to about 175°C. Fry in batches until crisp and golden, usually 2–3 minutes because the filling is already cooked.","Drain on a rack and serve with tonkatsu-style sauce or plain."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Korokke コロッケ Japanese food","Korokke Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_039","title":"Menchi Katsu","japaneseName":"メンチカツ","romanization":"menchi katsu","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":20,"total":50,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep fryer or heavy pot","ingredients":["300 g ground beef","200 g ground pork","1 small onion, finely diced","1 tsp neutral oil","40 g panko","60 ml milk","1 egg","1 tsp salt","1/4 tsp black pepper","50 g all-purpose flour","2 eggs, beaten, for coating","120 g panko for coating","neutral oil for deep-frying, as needed"],"steps":["Cook onion in 1 teaspoon oil until soft and translucent, then cool completely. Soak 40 g panko in milk.","Mix beef, pork, onion, soaked panko, egg, salt, and pepper until cohesive. Divide into six thick oval patties and chill 15 minutes.","Coat patties in flour, then beaten egg, then panko. Press gently so the crumb layer adheres.","Heat frying oil to about 170°C. Fry in batches, turning once, until deep golden and the center is fully cooked, about 6–8 minutes depending on thickness.","Drain on a rack and rest 3 minutes before serving.","Serve with shredded cabbage and tonkatsu sauce if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Menchi Katsu メンチカツ Japanese food","Menchi Katsu Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_040","title":"Ebi Fry","japaneseName":"エビフライ","romanization":"ebi furai","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":15,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep fryer or heavy pot","ingredients":["12 large shrimp","1/2 tsp salt and 1/4 tsp black pepper","50 g all-purpose flour","2 eggs, beaten","120 g panko","neutral oil for deep-frying, as needed","4 lemon wedges","tartar sauce, optional"],"steps":["Peel and devein shrimp, leaving tails on if desired. Make several shallow cuts on the underside, then gently straighten so they fry without curling tightly.","Pat very dry and season lightly. Coat each shrimp in flour, then beaten egg, then panko.","Heat oil to about 175°C. Fry shrimp in batches for about 2–3 minutes until golden and just cooked through.","Drain on a rack; do not pile hot fried shrimp because trapped steam softens the crust.","Serve immediately with lemon and tartar sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["shellfish","egg","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Ebi Fry エビフライ Japanese food","Ebi Fry Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_041","title":"Miso Soup with Tofu and Wakame","japaneseName":"豆腐とわかめの味噌汁","romanization":"tofu to wakame no misoshiru","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":10,"total":20,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["800 ml dashi","150 g silken or soft tofu, 2 cm cubes","2 tbsp dried wakame, rehydrated","3–4 tbsp miso, to taste","2 scallions, thinly sliced"],"steps":["Bring dashi to a gentle simmer. Add tofu and warm for 1–2 minutes without vigorous boiling.","Add rehydrated wakame and heat briefly.","Place miso in a ladle or small bowl, add some hot dashi, and stir until smooth.","Lower the heat or turn it off, then dissolve the thinned miso back into the soup. Avoid prolonged boiling after adding miso.","Taste and add a little more miso if needed.","Serve immediately with sliced scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Miso Soup with Tofu and Wakame 豆腐とわかめの味噌汁 Japanese food","Miso Soup with Tofu and Wakame Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_042","title":"Tonjiru","japaneseName":"豚汁","romanization":"tonjiru","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":30,"total":50,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"soup pot","ingredients":["200 g thinly sliced pork belly","1 tbsp neutral oil","1/2 daikon, about 250 g, half-moons","1 carrot, half-moons","150 g potato or satoimo, chunks","100 g gobo, shaved and rinsed","100 g konnyaku, torn into pieces","900 ml dashi","4 tbsp miso","2 scallions, sliced"],"steps":["Prepare vegetables in bite-size pieces. Briefly blanch konnyaku if strongly scented and drain.","Heat oil in a soup pot and cook pork until it loses most of its pink color.","Add daikon, carrot, potato, gobo, and konnyaku and stir for 2 minutes.","Add dashi, bring to a boil, skim foam, then simmer 15–20 minutes until the root vegetables are tender.","Turn the heat low. Dissolve miso with a little broth, then stir it back into the soup without prolonged boiling.","Serve hot with sliced scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Tonjiru 豚汁 Japanese food","Tonjiru Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_043","title":"Sukiyaki","japaneseName":"すき焼き","romanization":"sukiyaki","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"shallow hot pot","ingredients":["600 g very thinly sliced beef","1 block firm tofu, drained and cut","1 napa cabbage, about 500 g, chopped","200 g shiitake and enoki mushrooms","2 Japanese long onions or 4 scallions, large pieces","200 g shirataki noodles, rinsed","120 ml soy sauce","120 ml mirin","60 ml sake","3 tbsp sugar","4 pasteurized eggs, optional for dipping"],"steps":["Mix soy sauce, mirin, sake, and sugar for the warishita sauce. Prepare all ingredients and arrange them on platters before heating the pot.","Heat a shallow sukiyaki pot. Sear a few slices of beef briefly, sprinkle with a little sugar, then add a splash of warishita.","Move beef to the side and arrange tofu, cabbage, mushrooms, long onion, and shirataki around the pot. Add enough warishita to season without completely submerging everything.","Simmer gently, adding ingredients in batches as space opens. Avoid cooking thin beef for too long.","Adjust with a little water or dashi if the broth becomes too salty as it reduces.","Serve directly from the pot. If using raw egg as a dip, use eggs produced for raw consumption or pasteurized eggs; otherwise omit."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Sukiyaki すき焼き Japanese food","Sukiyaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_044","title":"Shabu-Shabu","japaneseName":"しゃぶしゃぶ","romanization":"shabu-shabu","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"tabletop hot pot","ingredients":["600 g paper-thin sliced beef or pork","1 L water","15 g kombu","300 g napa cabbage","200 g tofu","200 g mixed mushrooms","1 long onion, diagonal slices","200 g udon noodles, optional finish","120 ml ponzu sauce, for dipping","120 ml sesame dipping sauce"],"steps":["Soak kombu in 1 L water for 20–30 minutes in the hot pot. Warm slowly and remove the kombu just before the water boils.","Arrange meat, vegetables, tofu, mushrooms, and dipping sauces at the table.","Add firmer vegetables and tofu to the gently simmering kombu broth first.","Each diner swishes a slice of meat through the hot broth until fully cooked, then dips it in ponzu or sesame sauce.","Continue adding vegetables in manageable batches and skim foam as needed. Keep the broth at a simmer rather than a violent boil.","After the main ingredients are eaten, cook udon in the flavorful remaining broth if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Shabu-Shabu しゃぶしゃぶ Japanese food","Shabu-Shabu Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_045","title":"Oden","japaneseName":"おでん","romanization":"oden","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":80,"total":110,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide pot","ingredients":["1.5 L dashi","3 tbsp soy sauce","3 tbsp mirin","1 tsp salt","1/2 daikon, thick rounds","4 hard-boiled eggs","1 block konnyaku, cut into triangles","4 pieces chikuwa fish cake","4 pieces satsuma-age fish cake","1 block atsuage fried tofu, cut","mustard, to serve"],"steps":["Peel daikon rounds, round off sharp edges if desired, and simmer separately in water until partly tender.","Score konnyaku and blanch for 2 minutes.","Bring dashi, soy sauce, mirin, and salt to a gentle simmer in a wide pot.","Add daikon, eggs, and konnyaku first. Simmer very gently for about 30 minutes.","Blanch atsuage and fish cakes briefly with hot water to remove excess surface oil, then add them to the pot.","Continue simmering another 25–30 minutes. Turn off the heat and let the oden rest at least 20 minutes; cooling and reheating improves absorption.","Reheat gently without hard boiling and serve with Japanese mustard."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Oden おでん Japanese food","Oden Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_046","title":"Chanko Nabe","japaneseName":"ちゃんこ鍋","romanization":"chanko nabe","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":30,"total":60,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large hot pot","ingredients":["1.2 L dashi or chicken stock","3 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 tsp salt","400 g ground chicken","1 egg","2 tbsp potato starch","1 tbsp grated ginger","400 g napa cabbage","200 g tofu","200 g mixed mushrooms","1 carrot, sliced","2 scallions, large pieces"],"steps":["Mix ground chicken, egg, potato starch, ginger, and a pinch of salt until sticky. Shape into small meatballs with damp hands or two spoons.","Bring dashi or stock, soy sauce, mirin, sake, and salt to a gentle simmer.","Add chicken meatballs and cook 5–6 minutes, skimming foam, until firm and cooked through.","Add carrot, cabbage stems, tofu, and mushrooms. Simmer until nearly tender.","Add cabbage leaves and scallions last and cook just until softened.","Serve from the pot. Noodles or rice can be added to the remaining broth after the main ingredients are eaten."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chanko Nabe ちゃんこ鍋 Japanese food","Chanko Nabe Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_047","title":"Nigiri Sushi","japaneseName":"握り寿司","romanization":"nigiri-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":40,"cook":20,"total":60,"servings":4,"difficulty":"Hard","energy":"high","cleanup":3,"freezer":"no","equipment":"sharp sashimi knife","ingredients":["600 g cooked Japanese short-grain rice","80 ml rice vinegar","35 g sugar","10 g salt","400 g assorted sashimi-grade fish, sliced into 20 pieces","wasabi, optional","soy sauce, to serve"],"steps":["While the rice is hot, combine rice vinegar, sugar, and salt until dissolved. Fold the seasoning through the rice with a slicing motion while fanning until glossy and just warm.","Keep sushi rice covered with a damp cloth at room temperature while working; do not refrigerate it before shaping because it hardens.","Use fish specifically sold for raw consumption and maintain an unbroken cold chain.","Slice across the grain into pieces large enough to drape over a rice mound.","Moisten your hands lightly with vinegared water. Shape about 25 g rice into a compact oval without crushing the grains.","Place a tiny amount of wasabi on the fish if desired, lay the fish over the rice, and gently press and shape the two together.","Serve promptly with soy sauce. Keep raw seafood chilled until assembly and discard any fish that has been held unsafely."],"notes":"Use only seafood intended for raw consumption. Raw seafood safety depends on species, freezing, handling, and local food regulations.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Nigiri Sushi 握り寿司 Japanese food","Nigiri Sushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_048","title":"Maki Sushi","japaneseName":"巻き寿司","romanization":"maki-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":15,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"bamboo sushi mat","ingredients":["500 g prepared sushi rice","4 sheets nori","1 cucumber, cut into long strips","100 g sashimi-grade tuna or cooked crab sticks","wasabi, optional","soy sauce, to serve"],"steps":["Prepare seasoned sushi rice and let it cool to body temperature. Keep it covered so the surface does not dry.","Lay a sheet of nori shiny-side down on a bamboo mat. With damp fingers, spread a thin, even layer of rice over about three-quarters of the sheet, leaving the far edge bare.","Arrange cucumber and tuna or cooked crab in a narrow line across the lower third. Avoid overfilling.","Lift the mat and roll firmly over the filling, then continue rolling while applying even pressure to form a cylinder.","Moisten the bare nori edge lightly and finish the roll seam-side down. Rest 2 minutes.","Use a sharp damp knife to cut each roll into 6–8 pieces, wiping the blade between cuts. Serve promptly."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Maki Sushi 巻き寿司 Japanese food","Maki Sushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_049","title":"Futomaki","japaneseName":"太巻き","romanization":"futomaki","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":20,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"bamboo sushi mat","ingredients":["600 g prepared sushi rice","4 full sheets nori","4 eggs","1 tbsp sugar","pinch of salt","1 cucumber, long strips","100 g seasoned shiitake mushrooms","100 g cooked spinach, squeezed dry","8 strips kanpyo, simmered until tender, optional","100 g cooked shrimp or imitation crab"],"steps":["Make a lightly sweet tamagoyaki with eggs, sugar, and salt; cool and cut into long strips.","Prepare all other fillings and remove excess moisture.","Place nori on a bamboo mat and spread sushi rice evenly, leaving a 2 cm border at the far edge.","Arrange several fillings in parallel lines across the lower third, balancing colors and textures rather than piling them in one spot.","Lift the mat over the fillings and tuck firmly, then roll forward in one steady motion while keeping the fillings centered.","Shape the finished roll with gentle pressure and let it rest seam-side down for 2 minutes.","Slice with a sharp damp knife into thick rounds and serve."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Futomaki 太巻き Japanese food","Futomaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_050","title":"Temaki Sushi","japaneseName":"手巻き寿司","romanization":"temaki-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":10,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"serving platters","ingredients":["600 g prepared sushi rice","8 sheets nori, halved","200 g sashimi-grade salmon or tuna, strips","1 cucumber, thin sticks","100 g tamagoyaki, cut into strips","100 g cooked shrimp or crab, optional","shiso leaves, optional","wasabi to taste and 60 ml soy sauce, for serving"],"steps":["Prepare seasoned sushi rice and all fillings before serving. Keep raw fish chilled until it reaches the table.","Cut nori sheets in half. Put one piece in your dry hand with the rough side facing up.","Spread a small amount of rice over the left half in a thin layer, leaving edges exposed.","Lay two or three fillings diagonally across the rice. Do not overfill.","Fold the bottom-left corner over the fillings and continue rolling into a cone. Eat immediately before the nori softens.","For a group meal, place rice, nori, and fillings separately on the table and let each diner assemble one temaki at a time."],"notes":"Use sashimi-grade seafood if serving fish raw; cooked seafood is a good alternative for easier home handling.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","shellfish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Temaki Sushi 手巻き寿司 Japanese food","Temaki Sushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_051","title":"Inari Sushi","japaneseName":"いなり寿司","romanization":"inari-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["500 g prepared sushi rice","8 aburaage tofu pouches","250 ml dashi","3 tbsp sugar","3 tbsp soy sauce","2 tbsp mirin","1 tbsp toasted sesame seeds, optional"],"steps":["Blanch aburaage in boiling water for 1 minute, drain, cool enough to handle, and press gently to remove excess oil.","Cut each aburaage piece to form a pocket if needed.","Simmer dashi, sugar, soy sauce, and mirin. Add aburaage and cook gently 10–12 minutes, turning occasionally, until seasoned and most liquid is absorbed.","Cool the pouches in the cooking liquid, then gently squeeze out excess liquid without tearing them.","Mix sesame seeds into sushi rice if desired. Divide rice into eight loose portions.","Open each pouch and fill with rice without packing too tightly. Fold the edges inward and serve seam-side down or open-side up."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Inari Sushi いなり寿司 Japanese food","Inari Sushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_052","title":"Chirashizushi","japaneseName":"ちらし寿司","romanization":"chirashi-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":20,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide serving bowl","ingredients":["700 g prepared sushi rice","3 eggs","1 tsp sugar","pinch of salt","150 g cooked shrimp","120 g sashimi-grade salmon or tuna, optional","100 g cucumber, thin slices","80 g seasoned shiitake mushrooms","60 g blanched snow peas","2 tbsp ikura salmon roe, optional","nori strips and sesame, optional"],"steps":["Prepare and season the sushi rice, then spread it in a wide bowl to cool to room temperature.","Cook the eggs as a very thin omelet, cool, then slice into fine kinshi tamago strips.","Prepare shrimp, cucumber, shiitake, snow peas, and any raw fish. Keep raw seafood chilled until the final assembly.","Gently mix a small portion of shiitake or sesame into the rice if desired, taking care not to mash the grains.","Spread the rice in a serving dish and arrange egg, shrimp, vegetables, and fish attractively over the surface.","Add ikura and nori at the end and serve promptly."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","shellfish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chirashizushi ちらし寿司 Japanese food","Chirashizushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_053","title":"Tamagoyaki","japaneseName":"卵焼き","romanization":"tamagoyaki","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":10,"total":20,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"tamagoyaki pan or small nonstick skillet","ingredients":["4 large eggs","2 tbsp dashi","1 tbsp sugar","1 tsp soy sauce","1 tsp mirin","pinch of salt","1 tsp neutral oil"],"steps":["Beat eggs with dashi, sugar, soy sauce, mirin, and salt without creating excessive foam. Strain if you want an especially smooth texture.","Heat a tamagoyaki pan or small nonstick skillet over medium-low heat and wipe with a thin film of oil.","Pour in a thin layer of egg. When mostly set but still moist on top, roll it toward one side of the pan.","Oil the exposed pan lightly, pour in another thin layer, lifting the existing roll so uncooked egg flows underneath.","Roll the cooked omelet back across the new layer. Repeat until all egg is used, adjusting heat so it sets without browning heavily.","Shape the hot roll with a bamboo mat if desired, rest 2–3 minutes, then slice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Tamagoyaki 卵焼き Japanese food","Tamagoyaki Japanese food"],"origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_054","title":"Agedashi Tofu","japaneseName":"揚げ出し豆腐","romanization":"agedashi dofu","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"small pot or deep skillet","ingredients":["400 g firm or medium-firm tofu","50 g potato starch","neutral oil for frying, as needed","250 ml dashi","2 tbsp soy sauce","2 tbsp mirin","80 g grated daikon","1 tsp grated ginger","2 scallions, sliced","katsuobushi, optional"],"steps":["Wrap tofu in paper towels and drain under a light weight for 15 minutes, then cut into 8 pieces.","Simmer dashi, soy sauce, and mirin for 2 minutes to make the broth; keep warm.","Pat tofu dry again and coat every side lightly with potato starch just before frying.","Heat 2–3 cm oil to about 175°C. Fry tofu in batches until the coating is crisp and pale golden, about 2–3 minutes.","Drain briefly, place in shallow bowls, and pour warm broth around—not directly over—the crispest top surfaces.","Finish with grated daikon, ginger, scallion, and katsuobushi if using."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Agedashi Tofu 揚げ出し豆腐 Japanese food","Agedashi Tofu Japanese food"],"origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_055","title":"Horenso Goma-ae","japaneseName":"ほうれん草の胡麻和え","romanization":"horenso no goma-ae","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":5,"total":15,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"pot and mortar","ingredients":["300 g spinach","3 tbsp toasted sesame seeds","1 1/2 tbsp soy sauce","1 tbsp sugar","1 tbsp dashi or water"],"steps":["Bring a pot of water to a boil. Blanch spinach stems first for about 20 seconds, then submerge the leaves and cook another 30–40 seconds.","Transfer immediately to cold water. Squeeze out water firmly but gently, align the stems, and cut into 4 cm lengths.","Grind toasted sesame seeds until fragrant but not completely paste-like.","Mix sesame with soy sauce, sugar, and dashi or water.","Toss spinach with the sesame dressing just before serving so it remains fresh-tasting."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Horenso Goma-ae ほうれん草の胡麻和え Japanese food","Horenso Goma-ae Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_056","title":"Kinpira Gobo","japaneseName":"きんぴらごぼう","romanization":"kinpira gobo","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":12,"total":27,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["250 g gobo burdock root","1 small carrot","1 tbsp sesame oil","1 tbsp sugar","1 1/2 tbsp soy sauce","1 tbsp mirin","1 tbsp sake","1 tsp toasted sesame seeds","small pinch chili flakes, optional"],"steps":["Scrub gobo well, cut into fine matchsticks, and place briefly in water while cutting to reduce discoloration. Drain thoroughly. Julienne carrot similarly.","Heat sesame oil in a skillet over medium-high heat. Stir-fry gobo for 2–3 minutes, then add carrot.","Add sugar, sake, and mirin and stir until the vegetables begin to soften.","Add soy sauce and continue stir-frying until the liquid has mostly evaporated and the vegetables are tender with a slight bite.","Finish with sesame seeds and a tiny pinch of chili if desired.","Cool slightly before serving; kinpira is good warm or at room temperature."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Kinpira Gobo きんぴらごぼう Japanese food","Kinpira Gobo Japanese food"],"origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_057","title":"Cucumber Sunomono","japaneseName":"きゅうりの酢の物","romanization":"kyuri no sunomono","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":0,"total":20,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"mixing bowl","ingredients":["2 Japanese or Persian cucumbers, thinly sliced","1/2 tsp salt","3 tbsp rice vinegar","1 1/2 tbsp sugar","1 tsp soy sauce","1 tbsp toasted sesame seeds","2 tbsp rehydrated wakame, optional"],"steps":["Slice cucumbers very thinly. Toss with salt and rest 10 minutes.","Squeeze the cucumbers gently but thoroughly to remove excess water.","Stir rice vinegar, sugar, and soy sauce until the sugar dissolves.","Combine cucumber with wakame if using and toss with the dressing.","Chill 5–10 minutes, then sprinkle with sesame just before serving."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Cucumber Sunomono きゅうりの酢の物 Japanese food","Cucumber Sunomono Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_058","title":"Chawanmushi","japaneseName":"茶碗蒸し","romanization":"chawanmushi","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer and heatproof cups","ingredients":["3 large eggs","450 ml dashi, cooled","1 tbsp light soy sauce","1 tbsp mirin","1/2 tsp salt","120 g chicken thigh, small pieces","4 shrimp, peeled and deveined","4 shiitake mushrooms, sliced","4 slices kamaboko","mitsuba, optional"],"steps":["Lightly beat eggs without foaming.","Mix in cooled dashi, soy sauce, mirin, and salt, then strain for a smooth custard.","Divide chicken, shrimp, shiitake, and kamaboko among four heatproof cups.","Pour egg mixture into cups, leaving a little headspace. Remove surface bubbles with a spoon or skewer.","Cover cups loosely with foil. Steam over gentle—not aggressively boiling—water for about 15–18 minutes.","Check the center: the custard should be softly set and clear broth should appear when pierced; the chicken and shrimp must be fully cooked.","Garnish with mitsuba and serve warm."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","shellfish","fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Chawanmushi 茶碗蒸し Japanese food","Chawanmushi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"auditStatus":"Reviewed 2026"},{"id":"jp_059","title":"Dorayaki","japaneseName":"どら焼き","romanization":"dorayaki","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":6,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["2 large eggs","80 g sugar","1 tbsp honey","120 g cake flour","1 tsp baking powder","50 ml water","1 tsp neutral oil","300 g sweet red bean paste"],"steps":["Whisk eggs, sugar, and honey until the sugar is mostly dissolved and the mixture looks slightly thickened.","Sift in cake flour and baking powder and fold until smooth. Add water gradually to make a thick but pourable batter. Rest 10 minutes.","Heat a nonstick skillet over low-medium heat and wipe with the thinnest film of oil, then wipe almost all of it away.","Pour small rounds of batter. Cook until bubbles cover the surface and edges look set, about 1–2 minutes, then flip and cook 30–60 seconds.","Cool pancakes under a clean towel so they stay soft.","Sandwich a generous spoonful of red bean paste between two pancakes, matching similar-size pieces."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Dorayaki どら焼き Japanese food","Dorayaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"dessertStyle":"Cakes & griddled","auditStatus":"Reviewed 2026"},{"id":"jp_060","title":"Daifuku Mochi","japaneseName":"大福","romanization":"daifuku","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":10,"total":35,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer or microwave","ingredients":["150 g shiratamako glutinous rice flour","180 ml water","60 g sugar","240 g smooth red bean paste","potato starch for dusting, as needed"],"steps":["Divide red bean paste into 8 balls and chill while making the mochi.","Mix shiratamako and water until smooth, then stir in sugar.","Steam the mixture in a heatproof bowl for about 10–12 minutes, stirring once halfway, until translucent and very sticky. A microwave can also be used in short intervals.","Dust a tray generously with potato starch.","Scrape the hot mochi onto the tray and dust the top; cool just enough to handle.","Divide into 8 pieces. Flatten one piece with starch-dusted fingers, place an anko ball in the center, and stretch the mochi around it.","Pinch the seam closed, place seam-side down, and brush off excess starch. Best eaten the same day."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Daifuku Mochi 大福 Japanese food","Daifuku Mochi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_061","title":"Warabi Mochi","japaneseName":"わらび餅","romanization":"warabi mochi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":40,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["80 g warabi-mochiko or warabi starch blend","400 ml water","50 g sugar","50 g kinako roasted soybean flour","20 g sugar for kinako","pinch of salt","kuromitsu black sugar syrup, optional"],"steps":["Mix warabi starch, water, and 50 g sugar in a saucepan until completely smooth before turning on the heat.","Cook over medium-low heat, stirring continuously with a sturdy spatula. The mixture will turn from milky to translucent and very thick.","Continue stirring 2–3 minutes after it becomes translucent so the starch cooks fully.","Spread into a lightly wet shallow tray and cool, then chill 20 minutes; do not freeze.","Mix kinako with 20 g sugar and a pinch of salt. Cut or pinch the chilled mochi into bite-size pieces and coat generously.","Serve with kuromitsu if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Warabi Mochi わらび餅 Japanese food","Warabi Mochi Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_062","title":"Taiyaki","japaneseName":"たい焼き","romanization":"taiyaki","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"taiyaki pan","ingredients":["150 g cake flour","1 tsp baking powder","1/4 tsp baking soda","1 large egg","35 g sugar","180 ml milk","1 tsp neutral oil","240 g sweet red bean paste"],"steps":["Sift flour, baking powder, and baking soda. In another bowl whisk egg, sugar, and milk, then combine with dry ingredients just until smooth. Rest 10 minutes.","Preheat a taiyaki pan over medium-low heat and brush both sides very lightly with oil.","Pour a thin layer of batter into each fish mold, spreading it toward the tail. Add red bean paste in a narrow mound through the center.","Cover the filling with a little more batter, close the pan, and cook about 2–3 minutes.","Flip the pan and cook another 2–3 minutes, adjusting heat to brown the shell without burning it.","Open carefully, remove taiyaki, and cool on a rack for a few minutes so the exterior stays crisp."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Taiyaki たい焼き Japanese food","Taiyaki Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"dessertStyle":"Cakes & griddled","auditStatus":"Reviewed 2026"},{"id":"jp_063","title":"Japanese Purin","japaneseName":"プリン","romanization":"purin","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":120,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"oven and ramekins","ingredients":["80 g sugar for caramel","2 tbsp water","1 tbsp hot water","3 large eggs","2 egg yolks","500 ml whole milk","70 g sugar","1 tsp vanilla extract"],"steps":["Make caramel by heating 80 g sugar with 2 tablespoons water without stirring until amber. Carefully add 1 tablespoon hot water, swirl, and divide among six heatproof cups.","Heat milk with 70 g sugar just until steaming and the sugar dissolves; do not boil.","Whisk eggs and yolks gently. Gradually whisk in warm milk, then vanilla, avoiding excessive foam. Strain the custard.","Pour into caramel-lined cups and cover loosely with foil. Place in a deep baking dish and add hot water halfway up the cups.","Bake at 150°C for about 30–35 minutes until edges are set and centers still tremble slightly.","Cool, refrigerate at least 1 hour, then loosen edges and invert onto plates."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","milk"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Japanese Purin プリン Japanese food","Japanese Purin Japanese food"],"origin":"Japan","profile":"Popular classic","seasonality":"All year","tags":["Popular classic","Japan","All year"],"dessertStyle":"Chilled & café","auditStatus":"Reviewed 2026"},{"id":"jp_064","title":"Castella","japaneseName":"カステラ","romanization":"kasutera","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":120,"servings":10,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"stand mixer or hand mixer and loaf pan","ingredients":["6 large eggs, room temperature","180 g sugar","2 tbsp honey","2 tbsp warm water","180 g bread flour, sifted","1 tbsp neutral oil for pan"],"steps":["Line a tall rectangular cake pan completely with parchment. Preheat oven to 160°C. Dissolve honey in warm water.","Beat eggs and sugar over a warm-water bath until the mixture is slightly warm, then remove from heat and whip until very thick, pale, and able to hold a ribbon.","Fold in the honey mixture. Sift in bread flour in several additions and fold gently but thoroughly so no dry pockets remain.","Pour batter into the lined pan. Tap lightly and run a skewer through the batter to break large bubbles.","Bake about 40–45 minutes until deep golden and a skewer comes out clean.","While still warm, wrap the cake tightly once it can be handled and rest several hours or overnight; this redistributes moisture and gives castella its characteristic fine, moist crumb. Slice with a sharp knife."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","photoQueries":["Castella カステラ Japanese food","Castella Japanese food"],"origin":"Nagasaki","profile":"Regional sweet","seasonality":"All year","tags":["Regional sweet","Nagasaki","All year"],"dessertStyle":"Cakes & griddled","auditStatus":"Reviewed 2026"},{"id":"jp_065","title":"Yaki Onigiri","japaneseName":"焼きおにぎり","romanization":"yaki onigiri","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":22,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"nonstick skillet or grill pan","ingredients":["360 g warm cooked Japanese short-grain rice","2 tsp soy sauce","1 tsp mirin","1 tsp neutral oil","1 tsp toasted sesame seeds, optional"],"steps":["Let the cooked rice cool just enough to handle while it is still warm and sticky. Divide into 4 equal portions.","Wet clean hands lightly and shape each portion into a firm triangle or round about 2 cm thick; press enough to hold together without compacting the grains hard.","Mix soy sauce and mirin. Lightly oil a skillet and heat over medium. Cook the rice balls 3–4 minutes per side until a dry golden crust forms.","Brush the top sides sparingly with the soy mixture, flip, and cook 30–45 seconds. Brush the second sides, flip once more, and cook until fragrant and lightly caramelized.","Rest for 1 minute so the crust firms. Sprinkle with sesame if using and serve hot."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.kikkoman.com/en/cookbook/recipe/00001881.html","https://www.kikkoman.com/en/cookbook/feature/0001.html"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Yaki Onigiri 焼きおにぎり Japanese food","Yaki Onigiri Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_066","title":"Sekihan","japaneseName":"赤飯","romanization":"sekihan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":55,"total":190,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"yes","equipment":"rice cooker or heavy pot, small saucepan","ingredients":["360 g Japanese glutinous rice","120 g Japanese short-grain rice","80 g dried azuki beans or sasage beans","900 ml water, for boiling beans","about 430 ml reserved bean cooking liquid plus water","1 tsp salt","2 tbsp black sesame seeds","1/2 tsp fine salt for gomashio"],"steps":["Rinse the azuki. Cover with 900 ml water, bring to a boil for 2 minutes, drain, then cover with fresh water and simmer 20–25 minutes until the beans are tender at the edges but not splitting.","Drain the beans over a bowl and save the reddish cooking liquid. Cool both. Rinse the glutinous and short-grain rice together until the water is mostly clear, then drain 20 minutes.","Put rice in a rice cooker or heavy pot. Add enough reserved bean liquid and water to equal about 430 ml, then add 1 tsp salt and scatter the beans over the top without stirring them deeply into the rice.","Cook using the regular rice setting, or bring to a boil in a covered heavy pot, reduce to very low heat for 12–15 minutes, then turn off the heat and steam 15 minutes.","Mix black sesame with 1/2 tsp salt. Gently fold the cooked rice from the bottom so the beans stay mostly whole.","Serve warm or at room temperature with gomashio sprinkled over each portion."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional / celebration","seasonality":"Celebrations","tags":["Traditional / celebration","Japan","Celebrations"],"photoQueries":["Sekihan 赤飯 Japanese red rice","Sekihan Japanese celebration rice"],"auditStatus":"Reviewed 2026"},{"id":"jp_067","title":"Okayu","japaneseName":"お粥","romanization":"okayu","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":40,"total":45,"servings":2,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"small heavy pot with lid","ingredients":["100 g Japanese short-grain rice","700 ml water","1/4 tsp salt, plus more to taste","1 umeboshi, optional","2 tbsp sliced scallion or mitsuba, optional"],"steps":["Rinse the rice gently once or twice; it does not need to be washed completely clear. Drain.","Combine rice and 700 ml water in a small heavy pot. Bring to a boil uncovered over medium heat, stirring once so no grains stick to the bottom.","Reduce to the lowest heat, leave the lid slightly ajar, and simmer about 30–35 minutes. Stir only once or twice so the grains stay soft but distinct.","When the rice is tender and suspended in a loose, creamy broth, season lightly with salt. Add a little hot water if you prefer a thinner porridge.","Rest covered for 5 minutes. Serve plain or with umeboshi and scallion or mitsuba on top."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Okayu お粥 Japanese rice porridge","Japanese okayu rice porridge"],"auditStatus":"Reviewed 2026"},{"id":"jp_068","title":"Zosui","japaneseName":"雑炊","romanization":"zosui","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"medium saucepan","ingredients":["300 g cooked Japanese short-grain rice","600 ml dashi","80 g boneless chicken thigh, thinly sliced","2 fresh shiitake mushrooms, thinly sliced","60 g daikon, thinly sliced","1 tbsp soy sauce","1 tbsp sake","1/2 tsp salt","1 large egg, lightly beaten","2 tbsp sliced scallion or mitsuba"],"steps":["Rinse the cooked rice briefly under cool water and drain; this removes excess surface starch so the broth stays light rather than gluey.","Bring dashi, soy sauce, sake, and salt to a gentle simmer. Add chicken, shiitake, and daikon and cook 5–6 minutes until the chicken is cooked through and the daikon is tender.","Add the drained rice and simmer gently for 3–4 minutes. Do not boil hard or stir aggressively.","Drizzle the beaten egg over the surface. Cover and cook on low for about 45 seconds, then turn off the heat and let it finish setting for another minute.","Top with scallion or mitsuba and serve immediately while the zosui is loose and brothy."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Zosui 雑炊 Japanese food","Zosui Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_069","title":"Kuri Gohan","japaneseName":"栗ご飯","romanization":"kuri gohan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":45,"total":75,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"yes","equipment":"rice cooker or heavy pot","ingredients":["360 g Japanese short-grain rice","250 g peeled fresh chestnuts","430 ml water","2 tbsp sake","1 tsp salt","1 piece kombu, about 5 cm square","2 tsp black sesame seeds, optional"],"steps":["Rinse the rice until the water is mostly clear and drain for 20 minutes. If using raw chestnuts, peel away both the hard outer shell and inner skin, then soak the kernels in water as you work.","Put rice, 430 ml water, sake, and salt into the rice cooker or pot and stir once. Lay kombu on top.","Drain the chestnuts and arrange them over the rice without stirring. Cook on a normal rice setting, or cook covered on the stovetop using your usual Japanese-rice method.","When cooking finishes, leave covered for 10–15 minutes. Remove the kombu.","Fold gently from the bottom so some chestnuts remain in large pieces. Serve with black sesame if desired."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Seasonal home-style","seasonality":"Autumn","tags":["Seasonal home-style","Japan","Autumn"],"photoQueries":["Kuri gohan 栗ご飯 chestnut rice","Japanese chestnut rice kuri gohan"],"auditStatus":"Reviewed 2026"},{"id":"jp_070","title":"Takenoko Gohan","japaneseName":"たけのこご飯","romanization":"takenoko gohan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":45,"total":60,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"yes","equipment":"rice cooker or heavy pot","ingredients":["360 g Japanese short-grain rice","180 g boiled bamboo shoot, sliced","1 sheet aburaage fried tofu, about 40 g, cut into strips","400 ml dashi","2 tbsp usukuchi soy sauce or regular soy sauce","2 tbsp sake","1 tbsp mirin","1/2 tsp salt","2 tbsp kinome or sliced mitsuba, optional"],"steps":["Rinse the rice until the water is mostly clear and drain 20 minutes. Slice the bamboo shoot so both tender tips and firmer base pieces are represented.","Briefly pour hot water over the aburaage, blot, and slice into thin strips to remove excess surface oil.","Combine dashi, soy sauce, sake, mirin, and salt. Put rice in the cooker and add the seasoned dashi to the appropriate level for 2 rice-cooker cups, reserving a spoonful if necessary.","Scatter bamboo shoot and aburaage over the rice without mixing them deeply in. Cook on the regular rice setting.","Steam 10 minutes after cooking, then fold gently from the bottom. Garnish with kinome or mitsuba if available."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Seasonal home-style","seasonality":"Spring","tags":["Seasonal home-style","Japan","Spring"],"photoQueries":["Takenoko Gohan たけのこご飯 Japanese food","Takenoko Gohan Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_071","title":"Tai Meshi","japaneseName":"鯛めし","romanization":"tai meshi","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":45,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker or heavy pot, grill pan or broiler","ingredients":["360 g Japanese short-grain rice","350 g sea bream fillet with skin, pin bones removed","1/2 tsp salt for fish","400 ml dashi","2 tbsp sake","1 1/2 tbsp usukuchi soy sauce or regular soy sauce","1 tbsp mirin","1 piece kombu, about 5 cm square","1 tsp finely grated ginger, optional","2 tbsp mitsuba, sliced"],"steps":["Salt the sea bream and leave 10 minutes, then pat dry. Broil or sear skin-side down until lightly browned; it does not need to cook completely.","Rinse the rice until mostly clear and drain 20 minutes. Combine dashi, sake, soy sauce, and mirin.","Put rice and seasoned dashi into a rice cooker or pot. Lay kombu on top, then place the browned sea bream over it.","Cook on the regular rice setting. After cooking, rest covered 10 minutes.","Lift out the fish and kombu. Remove any remaining bones carefully, flake the fish into large pieces, and fold it back through the rice with ginger if using.","Serve hot with mitsuba."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Ehime and other coastal regions","profile":"Regional / traditional","seasonality":"All year","tags":["Regional / traditional","Ehime and other coastal regions","All year"],"photoQueries":["Tai meshi 鯛めし Ehime","Japanese sea bream rice tai meshi"],"auditStatus":"Reviewed 2026"},{"id":"jp_072","title":"Obihiro Butadon","japaneseName":"帯広豚丼","romanization":"obihiro butadon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"large skillet or grill pan","ingredients":["360 g hot cooked Japanese short-grain rice","280 g pork loin or pork belly, sliced 5–7 mm thick","2 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 1/2 tbsp sugar","1 tsp neutral oil","2 tbsp sliced scallion, optional"],"steps":["Combine soy sauce, mirin, sake, and sugar in a small bowl until the sugar starts dissolving.","Heat a skillet over medium-high and add a very thin film of oil. Cook the pork in a single layer until browned on the first side, then turn and cook until just done. Work in batches if needed.","Lower the heat to medium. Return all pork to the pan and pour in the sauce. Simmer 1–2 minutes, turning the slices, until the sauce becomes glossy and clings to the meat.","Divide hot rice between bowls. Arrange pork over the rice and spoon over enough pan sauce to season the rice without soaking it.","Top with scallion if using and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.japan.travel/en/destinations/hokkaido/hokkaido/","https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Obihiro, Hokkaido","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Obihiro, Hokkaido","All year"],"photoQueries":["Obihiro butadon 帯広豚丼 Hokkaido","Butadon Obihiro pork bowl"],"auditStatus":"Reviewed 2026"},{"id":"jp_073","title":"Kaisendon","japaneseName":"海鮮丼","romanization":"kaisendon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":0,"total":20,"servings":2,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"sharp knife, 2 serving bowls","ingredients":["360 g hot cooked Japanese short-grain rice","2 tbsp rice vinegar","2 tsp sugar","1/2 tsp salt","80 g sashimi-grade tuna","80 g sashimi-grade salmon","60 g sashimi-grade white fish or yellowtail","4 sashimi-grade shrimp or 60 g cooked shrimp","2 tbsp ikura salmon roe, optional","1/2 cucumber, thinly sliced","1/2 sheet nori, shredded","2 tsp soy sauce, for serving","1 tsp wasabi, optional"],"steps":["Mix rice vinegar, sugar, and salt until dissolved. Fold into the hot rice and cool until warm; plain Japanese rice is also traditional in some seafood bowls.","Keep all seafood cold until the last moment. Slice fish cleanly across the grain into bite-size sashimi pieces.","Divide rice between bowls and arrange cucumber and nori around the edges.","Arrange the fish and shrimp over the rice, keeping each variety distinct; add ikura if using.","Serve immediately with soy sauce and wasabi. Use only seafood sold for raw consumption and keep it properly refrigerated; substitute cooked seafood if there is any doubt about raw-fish safety."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","shellfish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan, especially coastal markets","profile":"Popular seafood","seasonality":"All year","tags":["Popular seafood","Japan, especially coastal markets","All year"],"photoQueries":["Kaisendon 海鮮丼 Japanese seafood bowl","Japanese kaisendon sashimi rice bowl"],"auditStatus":"Reviewed 2026"},{"id":"jp_074","title":"Keihan","japaneseName":"鶏飯","romanization":"keihan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":70,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan, skillet","ingredients":["600 g hot cooked Japanese short-grain rice","300 g boneless chicken thigh or breast","1.2 L chicken stock or light chicken dashi","4 dried shiitake mushrooms, soaked and thinly sliced","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","2 large eggs","1 tsp neutral oil","60 g takuan or other mild Japanese pickles, finely sliced","1 sheet nori, finely shredded","2 tbsp sliced scallion","1 tsp grated yuzu peel or lemon zest, optional"],"steps":["Simmer the chicken gently in the stock until cooked through, about 12–15 minutes. Remove, cool slightly, and shred finely; keep the broth hot and skim excess fat.","Simmer the soaked shiitake with 1 tbsp soy sauce, 1 tbsp mirin, 1 tsp sugar, and 80 ml water until glossy and nearly dry.","Beat the eggs with a pinch of salt. Wipe a lightly oiled skillet with paper towel and cook thin omelet sheets; cool, roll, and cut into fine strips.","Season the chicken broth lightly with the remaining soy sauce and mirin. Taste before adding salt; the broth should be clear and savory.","Put a modest mound of rice in each bowl. Arrange shredded chicken, shiitake, egg, pickles, nori, and scallion neatly on top.","Pour plenty of piping-hot chicken broth over the rice at the table and finish with a little yuzu peel if using."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/149/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Amami Oshima, Kagoshima","profile":"Regional / niche","seasonality":"All year","tags":["Regional / niche","Amami Oshima, Kagoshima","All year"],"photoQueries":["Keihan 鶏飯 Amami Kagoshima","Amami keihan chicken rice"],"auditStatus":"Reviewed 2026"},{"id":"jp_075","title":"Kake Udon","japaneseName":"かけうどん","romanization":"kake udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"2 saucepans","ingredients":["2 portions frozen or fresh udon noodles, about 400 g","700 ml dashi","2 tbsp usukuchi soy sauce or regular soy sauce","2 tbsp mirin","1/2 tsp salt","2 tbsp finely sliced scallion","1 tsp shichimi togarashi, optional"],"steps":["Bring a pot of water to a boil for the udon. In a second saucepan, combine dashi, soy sauce, mirin, and salt and bring just to a simmer.","Cook or reheat the udon according to its package directions, then drain thoroughly.","Taste the broth and adjust with a little salt or dashi; it should be clear and savory, not as concentrated as a dipping sauce.","Divide noodles between warmed bowls and pour the hot broth over them.","Top with scallion and shichimi if desired and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"photoQueries":["Kake Udon かけうどん Japanese food","Kake Udon Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_076","title":"Kamaage Udon (Sanuki-Style)","japaneseName":"釜揚げうどん","romanization":"kamaage udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":20,"total":95,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large bowl, rolling pin, large pot","ingredients":["400 g all-purpose or udon flour","180 ml water","18 g fine salt","8 g cornstarch or potato starch, for dusting","300 ml dashi","75 ml soy sauce","60 ml mirin","2 tbsp grated ginger","4 tbsp sliced scallion"],"steps":["Dissolve salt in the water. Put flour in a bowl and gradually work in the salted water until shaggy, then knead 8–10 minutes until smooth and elastic.","Wrap and rest the dough 30 minutes. Roll to about 3 mm thick, dusting with starch, fold loosely, and cut into 3–4 mm noodles. Shake apart.","For the dipping sauce, simmer dashi, soy sauce, and mirin for 2 minutes, then keep warm.","Boil the noodles in plenty of unsalted water until chewy-tender, usually 10–13 minutes depending on thickness. For kamaage, do not rinse.","Transfer noodles with some cooking water to a serving bowl. Serve the warm dipping sauce separately with ginger and scallion."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kagawa / Sanuki","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Kagawa / Sanuki","All year"],"photoQueries":["Sanuki kamaage udon 釜揚げうどん Kagawa","Kamaage udon Sanuki"],"auditStatus":"Reviewed 2026"},{"id":"jp_077","title":"Miso Nikomi Udon","japaneseName":"味噌煮込みうどん","romanization":"miso nikomi udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":25,"total":40,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"donabe or medium heavy pot","ingredients":["2 portions firm fresh udon, about 400 g","700 ml dashi","70 g hatcho miso or red miso","1 tbsp mirin","1 tbsp sake","180 g boneless chicken thigh, bite-size pieces","2 fresh shiitake mushrooms, sliced","1/2 long negi or leek, diagonally sliced","80 g aburaage fried tofu, sliced","2 large eggs","2 tbsp sliced scallion"],"steps":["Bring dashi, mirin, and sake to a simmer in a donabe or heavy pot. Add chicken and shiitake and cook 5 minutes, skimming if needed.","Whisk miso with a ladleful of hot broth in a bowl until smooth, then stir it back into the pot. Avoid a violent boil after adding miso.","Add the udon, aburaage, and negi. Simmer until the noodles are cooked but still firm and the chicken is done, about 7–10 minutes.","Make two spaces in the noodles and crack in the eggs. Cover and cook 2–3 minutes, or until the whites set and yolks are as firm as you prefer.","Top with scallion and serve very hot."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Nagoya, Aichi","profile":"Regional favorite","seasonality":"Cool weather","tags":["Regional favorite","Nagoya, Aichi","Cool weather"],"photoQueries":["Miso nikomi udon 味噌煮込みうどん Nagoya","Nagoya miso nikomi udon"],"auditStatus":"Reviewed 2026"},{"id":"jp_078","title":"Houtou","japaneseName":"ほうとう","romanization":"hōtō","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":35,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large heavy pot, rolling pin","ingredients":["300 g all-purpose flour","130–150 ml lukewarm water","1/2 small kabocha squash, about 350 g, cut into chunks","1 medium potato, cut into chunks","1 medium carrot, sliced","120 g daikon, sliced","4 fresh shiitake mushrooms, sliced","1 sheet aburaage fried tofu, sliced","1.2 L dashi","80–100 g miso","1 long negi, sliced"],"steps":["Mix flour with 130 ml water and knead until a firm dough forms, adding only enough extra water to bring it together. Rest covered 20 minutes; traditional houtou dough is not salted like udon.","Roll the dough about 3 mm thick and cut into broad noodles roughly 1 cm wide. Do not pre-boil them.","Bring dashi to a simmer. Add potato, carrot, daikon, mushrooms, and kabocha and cook about 10 minutes.","Add aburaage and half the miso, then drop the raw noodles directly into the simmering broth. Cook 8–10 minutes, stirring gently so they do not stick; their flour will naturally thicken the broth.","Dissolve in the remaining miso to taste. Add negi, simmer 1 minute, then turn off the heat and rest covered 3 minutes before serving."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/918/index.html","https://www.maff.go.jp/e/policies/market/k_ryouri/areastory/1373/index.html"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Yamanashi","profile":"Regional / niche","seasonality":"Autumn / winter","tags":["Regional / niche","Yamanashi","Autumn / winter"],"photoQueries":["Houtou ほうとう Yamanashi noodles","Hoto noodles Yamanashi Japanese"],"auditStatus":"Reviewed 2026"},{"id":"jp_079","title":"Cold Somen with Tsuyu","japaneseName":"そうめん","romanization":"sōmen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":8,"total":18,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"saucepan, colander","ingredients":["200 g dried somen noodles","200 ml dashi","50 ml soy sauce","50 ml mirin","1 tsp sugar, optional","2 tbsp sliced scallion","1 tsp grated ginger","1/2 sheet nori, shredded","4 ice cubes, optional"],"steps":["Combine dashi, soy sauce, mirin, and sugar in a small saucepan. Bring to a brief simmer, then cool completely; chill if time allows.","Bring a large pot of water to a full boil. Add somen and cook according to the package, usually 1 1/2–2 minutes.","Drain immediately and rinse very thoroughly under cold running water, gently rubbing the noodles between your hands to remove surface starch. Chill in ice water for 30 seconds and drain well.","Divide the dipping sauce between small cups. Arrange somen in bowls or on a draining basket.","Serve with scallion, ginger, and nori for diners to add to the dipping sauce."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Seasonal classic","seasonality":"Summer","tags":["Seasonal classic","Japan","Summer"],"photoQueries":["Cold Somen with Tsuyu そうめん Japanese food","Cold Somen with Tsuyu Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_080","title":"Nyumen","japaneseName":"にゅうめん","romanization":"nyūmen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":22,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"2 saucepans","ingredients":["180 g dried somen noodles","700 ml dashi","1 1/2 tbsp usukuchi soy sauce or regular soy sauce","1 tbsp mirin","1/2 tsp salt","4 shiitake mushrooms, sliced","80 g spinach, trimmed","2 tbsp sliced scallion","1 tsp grated ginger, optional"],"steps":["Bring a pot of water to a boil and cook the somen about 30 seconds less than the package time. Drain and rinse briefly so the final soup stays clear.","In a second saucepan, bring dashi, soy sauce, mirin, and salt to a simmer. Add shiitake and cook 3–4 minutes.","Add spinach and cook just until wilted.","Add the drained somen to the broth and heat for 30–60 seconds without overcooking the thin noodles.","Divide into bowls and top with scallion and ginger if using."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style / niche","seasonality":"Cool weather","tags":["Home-style / niche","Japan","Cool weather"],"photoQueries":["Nyumen にゅうめん Japanese food","Nyumen Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_081","title":"Tsukemen","japaneseName":"つけ麺","romanization":"tsukemen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":55,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 saucepans, fine strainer","ingredients":["300 g fresh ramen noodles","500 ml unsalted chicken stock","120 ml dashi","2 tbsp soy sauce","1 tbsp mirin","1 tbsp sake","1 tbsp white miso","1 tsp rice vinegar","1 tsp sesame oil","1 tsp grated ginger","1 clove garlic, grated","120 g cooked chashu pork, sliced","1 soft-boiled egg, halved","1/2 sheet nori","2 tbsp sliced scallion"],"steps":["Simmer chicken stock and dashi uncovered for about 15 minutes to concentrate slightly. Add soy sauce, mirin, sake, ginger, and garlic and simmer 5 minutes.","Whisk in miso, then finish with rice vinegar and sesame oil. Keep the dipping broth hot but do not reduce it until overly salty.","Cook the ramen noodles in plenty of boiling water until just chewy. Drain and rinse thoroughly under cold water, then drain very well.","Arrange cold noodles in serving bowls with nori. Put chashu, egg, and scallion alongside or on top.","Divide the hot concentrated broth between small bowls. Dip a bite-size portion of noodles into the broth as you eat; dilute leftover broth with hot dashi if desired at the end."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Modern popular","seasonality":"All year","tags":["Modern popular","Japan","All year"],"photoQueries":["Tsukemen つけ麺 Japanese dipping ramen","Japanese tsukemen noodles"],"auditStatus":"Reviewed 2026"},{"id":"jp_082","title":"Abura Soba","japaneseName":"油そば","romanization":"abura soba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":10,"total":20,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"large pot, 2 serving bowls","ingredients":["300 g fresh ramen noodles","2 tbsp soy sauce","1 tbsp rice vinegar","1 tbsp sesame oil","1 tbsp neutral oil or rendered chicken fat","1 tsp sugar","1 tsp chili oil, optional","120 g cooked chashu pork, sliced","1 soft-boiled egg, halved","2 tbsp sliced scallion","1/2 sheet nori, shredded","1 tbsp toasted sesame seeds"],"steps":["Mix soy sauce, vinegar, sesame oil, neutral oil, sugar, and chili oil if using. Divide this tare between two warmed bowls.","Cook ramen noodles until chewy-tender. Drain extremely well; excess water will dilute the sauce.","Immediately put the hot noodles into the bowls and toss thoroughly from the bottom until every strand is glossy.","Top with chashu, egg, scallion, nori, and sesame.","Serve at once. Add a few drops of extra vinegar or chili oil at the table if desired."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Modern / niche","seasonality":"All year","tags":["Modern / niche","Japan","All year"],"photoQueries":["Abura Soba 油そば Japanese food","Abura Soba Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_083","title":"Nagasaki Champon","japaneseName":"長崎ちゃんぽん","romanization":"nagasaki chanpon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large wok or deep skillet","ingredients":["2 portions Nagasaki champon noodles or fresh thick Chinese wheat noodles, about 300 g","80 g pork belly, thinly sliced","80 g shelled shrimp","80 g cleaned squid, sliced","60 g kamaboko fish cake, sliced","100 g cabbage, chopped","100 g bean sprouts","40 g carrot, thinly sliced","2 shiitake mushrooms, sliced","400 ml chicken stock","2 tsp oyster sauce","1 tbsp sake","1/2 tsp sugar","1/2 tsp salt","1 tbsp neutral oil"],"steps":["Prepare all ingredients before heating the wok because the stir-fry moves quickly. Mix chicken stock, oyster sauce, sake, sugar, and salt.","Heat oil over high heat. Stir-fry pork for about 1 minute, then add shrimp and squid and cook just until they begin changing color.","Add cabbage, carrot, mushrooms, kamaboko, and bean sprouts and stir-fry 2–3 minutes so the vegetables remain lively.","Pour in the seasoned stock and bring to a boil. Add the noodles directly to the soup; if your specific noodles require pre-boiling, follow the package and shorten this simmer.","Simmer until the noodles are cooked and have absorbed some soup, about 3–4 minutes. Taste the broth and adjust salt only at the end.","Divide noodles, toppings, and soup evenly between bowls and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/3351/index.html","https://www.japan.travel/en/destinations/kyushu/nagasaki/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","shellfish","fish","soy","mollusc"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Nagasaki","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Nagasaki","All year"],"photoQueries":["Nagasaki champon 長崎ちゃんぽん","Champon Nagasaki noodles"],"auditStatus":"Reviewed 2026"},{"id":"jp_084","title":"Okinawa Soba","japaneseName":"沖縄そば","romanization":"okinawa soba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":70,"total":95,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large pot, saucepan","ingredients":["4 portions Okinawa soba noodles or thick wheat noodles, about 600 g","700 g pork spare ribs or pork belly","1.5 L water","15 g katsuobushi bonito flakes","1 piece kombu, about 10 cm","3 tbsp soy sauce","2 tbsp awamori or sake","1 tbsp sugar","1 tsp salt, plus more to taste","8 slices kamaboko fish cake","4 tbsp sliced scallion","2 tbsp beni shoga pickled red ginger"],"steps":["Put pork in a pot, cover with water, bring to a boil for 3 minutes, then drain and rinse the pork and pot. Return pork with 1.5 L fresh water and kombu; simmer gently 45–60 minutes until tender.","Remove the pork. Strain the broth, then add bonito flakes off the heat for 3–4 minutes and strain again. Season the clear pork-bonito broth with 2 tbsp soy sauce and salt to taste.","For the pork topping, simmer the cooked pork with 100 ml broth, remaining 1 tbsp soy sauce, awamori or sake, and sugar for 10–15 minutes until glazed.","Cook or reheat the noodles according to their package and drain well.","Divide noodles among bowls, pour over hot broth, and top with pork, kamaboko, scallion, and beni shoga."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/pref/okinawa/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Okinawa","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Okinawa","All year"],"photoQueries":["Okinawa soba 沖縄そば","Okinawan soba noodle soup"],"auditStatus":"Reviewed 2026"},{"id":"jp_085","title":"Chikuzenni","japaneseName":"筑前煮","romanization":"chikuzenni","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":30,"total":55,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"yes","equipment":"large saucepan or sauté pan with lid","ingredients":["400 g boneless chicken thigh, bite-size pieces","200 g satoimo taro, peeled and halved","120 g carrot, cut into rolling chunks","120 g lotus root, peeled and sliced","100 g boiled bamboo shoot, cut into chunks","80 g gobo burdock root, cut into chunks","4 dried shiitake mushrooms, soaked and halved","150 g konnyaku, torn into bite-size pieces","1 tbsp sesame oil","350 ml dashi","3 tbsp mirin","2 tbsp soy sauce","2 tbsp sake","1 tbsp sugar","60 g snow peas, blanched"],"steps":["Prepare the root vegetables in similarly sized pieces. Briefly parboil taro and konnyaku separately, then drain; this keeps the finished broth cleaner.","Heat sesame oil in a wide pan over medium heat. Brown the chicken lightly, then add carrot, lotus root, bamboo shoot, gobo, mushrooms, taro, and konnyaku and stir-fry 2–3 minutes.","Add dashi, sake, and sugar. Bring to a simmer, skim, and cook covered 10 minutes.","Add mirin and soy sauce. Place a drop lid or parchment circle over the surface and simmer 12–15 minutes until the vegetables are tender and the liquid has reduced.","Remove the lid and gently turn the ingredients through the remaining glaze. Taste and adjust with a small splash of soy sauce if needed.","Transfer to a serving dish and scatter the blanched snow peas over the top."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.kikkoman.com/en/cookbook/recipe/00000205.html","https://www.maff.go.jp/e/policies/market/k_ryouri/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style classic","seasonality":"All year","tags":["Home-style classic","Japan","All year"],"photoQueries":["Chikuzenni 筑前煮 Japanese simmered chicken vegetables","Chikuzenni Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_086","title":"Buri Teriyaki","japaneseName":"ぶりの照り焼き","romanization":"buri no teriyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"nonstick skillet","ingredients":["2 yellowtail fillets, about 150 g each","1/4 tsp salt","1 tsp neutral oil","2 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 tbsp sugar","1 tsp grated ginger, optional"],"steps":["Lightly salt the yellowtail and leave 10 minutes, then blot away moisture; this reduces fishiness and helps browning.","Mix soy sauce, mirin, sake, sugar, and ginger if using.","Heat oil over medium. Cook the fish presentation-side down for 3–4 minutes until browned, turn, and cook another 2–3 minutes until nearly done.","Wipe excess oil from the pan. Pour in the sauce and simmer, spooning it over the fish, until glossy and reduced enough to coat the fillets.","Remove from heat before the glaze becomes sticky-burnt. Serve with the pan glaze spooned over the fish."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Popular","seasonality":"All year","tags":["Popular","Japan","All year"],"photoQueries":["Buri Teriyaki ぶりの照り焼き Japanese food","Buri Teriyaki Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_087","title":"Saba Shioyaki","japaneseName":"鯖の塩焼き","romanization":"saba no shioyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"fish grill, broiler, or skillet","ingredients":["2 mackerel fillets, about 150 g each","1 tsp fine salt","150 g daikon, finely grated and drained","2 lemon or sudachi wedges","2 tsp soy sauce, optional for daikon"],"steps":["Check the mackerel for pin bones and remove them. Sprinkle both sides evenly with salt and leave 15–20 minutes.","Blot the fish very dry with paper towels. This step removes moisture drawn out by the salt and improves the grilled skin.","Grill or broil skin-side toward the heat until blistered and browned, then cook the second side until opaque and juicy, about 10–15 minutes total depending on thickness.","Serve immediately with grated daikon and citrus. Add a few drops of soy sauce to the daikon only if desired."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style classic","seasonality":"All year","tags":["Home-style classic","Japan","All year"],"photoQueries":["Saba Shioyaki 鯖の塩焼き Japanese food","Saba Shioyaki Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_088","title":"Karei no Nitsuke","japaneseName":"カレイの煮付け","romanization":"karei no nitsuke","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":20,"total":30,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide shallow saucepan with lid","ingredients":["2 flounder or flatfish fillets, about 160 g each","150 ml water","100 ml sake","3 tbsp soy sauce","3 tbsp mirin","2 tbsp sugar","15 g fresh ginger, thinly sliced","2 portions blanched spinach or greens, optional"],"steps":["Pat the fish dry and make one shallow diagonal cut through the skin of each piece so it cooks evenly.","Combine water, sake, soy sauce, mirin, sugar, and ginger in a wide pan and bring to a strong simmer.","Place fish skin-side up in the simmering liquid. Spoon sauce over the top, cover with a drop lid or parchment, and simmer over medium-low 10–12 minutes.","Remove the drop lid and continue simmering 3–5 minutes, basting repeatedly, until the sauce is glossy and the fish flakes easily without becoming dry.","Serve the fish carefully with ginger and reduced sauce; add blanched greens alongside if using."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style / niche","seasonality":"All year","tags":["Home-style / niche","Japan","All year"],"photoQueries":["Karei no Nitsuke カレイの煮付け Japanese food","Karei no Nitsuke Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_089","title":"Goya Chanpuru","japaneseName":"ゴーヤーチャンプルー","romanization":"gōyā chanpurū","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large skillet or wok","ingredients":["300 g goya bitter melon","300 g firm momen tofu","100 g pork belly, thinly sliced","2 large eggs, beaten","2 tbsp neutral oil","1/2 tsp salt, plus more to taste","1 tbsp soy sauce","5 g katsuobushi bonito flakes, optional"],"steps":["Halve the goya lengthwise, scrape out seeds and white pith, and slice into thin half-moons. Sprinkle with a small pinch of salt and leave 10 minutes, then rinse and dry.","Drain the tofu well and tear it into large pieces. Heat 1 tbsp oil over medium-high and brown the tofu on several sides, then remove.","Add the remaining oil and pork. Stir-fry until cooked, then add goya and cook about 2 minutes; it should soften slightly but retain some bite.","Return the tofu and season lightly with salt and soy sauce. Pour the beaten egg over the pan and toss gently just until set.","Transfer immediately so the egg stays tender. Top with katsuobushi if using."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/3951/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","egg","fish","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Okinawa","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Okinawa","All year"],"photoQueries":["Goya chanpuru ゴーヤーチャンプルー Okinawa","Okinawan goya champuru"],"auditStatus":"Reviewed 2026"},{"id":"jp_090","title":"Rafute","japaneseName":"ラフテー","romanization":"rafutē","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":180,"total":200,"servings":6,"difficulty":"Medium","energy":"high","cleanup":2,"freezer":"yes","equipment":"heavy pot with lid","ingredients":["1 kg skin-on pork belly or boneless pork ribs","1.5 L water, for first simmer","800 ml bonito dashi","240 ml awamori or sake","120 g brown or black sugar","100 ml soy sauce","20 g fresh ginger, sliced, optional"],"steps":["Place pork in a heavy pot, cover with water, and bring to a boil. Reduce to a gentle simmer for 60–75 minutes, skimming as needed, until a skewer enters with moderate resistance.","Cool the pork enough to handle and cut into large 4–5 cm cubes. Strain and reserve a little pork broth if desired.","Return pork to the cleaned pot with bonito dashi, awamori, sugar, and ginger if using. Simmer gently for 30 minutes, partially covered.","Add half the soy sauce and simmer 30 minutes. Add the remaining soy sauce and continue simmering 30–45 minutes, turning the pieces occasionally.","The pork is ready when the skin and fat are very tender and the cooking liquid has reduced to a glossy sauce. Add a little hot water if the sauce reduces before the meat softens.","Rest in the sauce at least 15 minutes before serving; rafute becomes even more flavorful after cooling and reheating gently."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/2812/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Okinawa","profile":"Regional / traditional","seasonality":"All year","tags":["Regional / traditional","Okinawa","All year"],"photoQueries":["Rafute ラフテー Okinawa pork","Okinawan rafute"],"auditStatus":"Reviewed 2026"},{"id":"jp_091","title":"Jingisukan","japaneseName":"ジンギスカン","romanization":"jingisukan","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large cast-iron skillet or tabletop grill","ingredients":["500 g thinly sliced lamb shoulder or leg","1 medium onion, sliced","200 g bean sprouts","150 g cabbage, chopped","1 green bell pepper, sliced","1 tbsp neutral oil","1/2 apple, finely grated","1/4 onion, finely grated","3 tbsp soy sauce","2 tbsp sake","1 tbsp mirin","1 tbsp sugar","1 tsp grated ginger","1 clove garlic, grated"],"steps":["Mix grated apple and onion with soy sauce, sake, mirin, sugar, ginger, and garlic to make the dipping or finishing tare.","Arrange lamb and vegetables separately so the meat can cook quickly without steaming.","Heat a cast-iron skillet or grill until hot and lightly oil it. Cook onion, cabbage, pepper, and bean sprouts around the cooler edges.","Cook lamb in the hotter center in batches, about 1–2 minutes per side depending on thickness, until browned and cooked to your preferred safe doneness.","Dip cooked lamb and vegetables in the tare, or add a few spoonfuls to the pan near the end for a glazed style. Serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Hokkaido","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Hokkaido","All year"],"photoQueries":["Jingisukan ジンギスカン Hokkaido lamb","Hokkaido jingisukan"],"auditStatus":"Reviewed 2026"},{"id":"jp_092","title":"Hokkaido Soup Curry","japaneseName":"スープカレー","romanization":"sūpu karē","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":55,"total":80,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large pot, baking tray or skillet","ingredients":["4 bone-in chicken thighs or small whole legs","1 tsp salt","1 tbsp neutral oil","1 medium onion, finely chopped","2 cloves garlic, grated","15 g ginger, grated","2 tbsp curry powder","1 tsp garam masala","1/2 tsp ground cumin","1 tbsp tomato paste","1.2 L chicken stock","1 tbsp soy sauce","1 tsp honey or sugar","1 medium potato, halved","1 carrot, cut into large pieces","1/4 kabocha squash, sliced","1 small eggplant, halved","8 okra","4 servings hot Japanese rice"],"steps":["Season chicken with salt. Brown it in oil in a large pot over medium-high heat, then remove.","Lower to medium. Cook onion until golden, 8–10 minutes. Add garlic, ginger, curry powder, garam masala, cumin, and tomato paste and stir for 1 minute.","Return chicken and add stock, soy sauce, and honey. Simmer gently 25 minutes. Add potato and carrot and cook another 15–20 minutes until tender.","While the soup simmers, roast or pan-sear kabocha, eggplant, and okra with a little oil until browned and tender; keeping them separate preserves their texture.","Taste the soup and adjust salt and spice. It should be thinner and more broth-like than Japanese curry rice.","Put chicken and vegetables in deep bowls, ladle over curry soup, and serve steamed rice separately for dipping spoonfuls into the broth."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.japan.travel/en/destinations/hokkaido/hokkaido/","https://www.japan.travel/en/my/delicious-japan/hokkaido/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"medium","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Sapporo, Hokkaido","profile":"Regional modern classic","seasonality":"All year","tags":["Regional modern classic","Sapporo, Hokkaido","All year"],"photoQueries":["Hokkaido soup curry スープカレー Sapporo","Sapporo soup curry"],"auditStatus":"Reviewed 2026"},{"id":"jp_093","title":"Miso Katsu","japaneseName":"味噌カツ","romanization":"miso katsu","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep skillet or fryer, small saucepan","ingredients":["2 boneless pork loin chops, about 150 g each","1/2 tsp salt","1/4 tsp black pepper","30 g all-purpose flour","1 large egg, beaten","80 g panko breadcrumbs","neutral oil, for frying","3 tbsp hatcho miso or red miso","2 tbsp mirin","2 tbsp sake","1 1/2 tbsp sugar","2 tbsp water","150 g finely shredded cabbage"],"steps":["Pat pork dry, lightly score the fat edge so it stays flat, and season with salt and pepper. Coat in flour, egg, then panko, pressing gently so the crumbs adhere.","Heat 2–3 cm oil to 170°C. Fry the cutlets until golden and cooked through, about 4–5 minutes total depending on thickness. Drain on a rack and rest 3 minutes.","Meanwhile combine miso, mirin, sake, sugar, and water in a small saucepan. Simmer gently 2–3 minutes until smooth and glossy.","Slice the rested pork into strips.","Serve over or beside shredded cabbage and spoon the warm miso sauce over the cutlet just before eating so the crust stays crisp."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["pork","gluten","egg","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Nagoya, Aichi","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Nagoya, Aichi","All year"],"photoQueries":["Miso katsu 味噌カツ Nagoya","Nagoya miso katsu"],"auditStatus":"Reviewed 2026"},{"id":"jp_094","title":"Aji Nanbanzuke","japaneseName":"アジの南蛮漬け","romanization":"aji nanbanzuke","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":90,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep skillet, shallow nonreactive dish","ingredients":["500 g small horse mackerel fillets or other small oily fish","1/2 tsp salt","40 g potato starch or cornstarch","neutral oil, for frying","1/2 medium onion, very thinly sliced","1/2 carrot, julienned","1 small green bell pepper, thinly sliced","150 ml rice vinegar","100 ml dashi","3 tbsp soy sauce","3 tbsp sugar","1 tbsp mirin","1 dried red chili, sliced, optional"],"steps":["Combine rice vinegar, dashi, soy sauce, sugar, mirin, and chili in a saucepan. Warm just until the sugar dissolves, then pour into a shallow dish with onion, carrot, and bell pepper.","Pat the fish very dry, season lightly with salt, and coat thinly in potato starch, shaking off excess.","Heat 2–3 cm oil to about 170°C and fry the fish until crisp and cooked through. Drain briefly.","While the fish is still hot, place it directly into the marinade so it absorbs the sweet-sour seasoning. Spoon vegetables and liquid over the top.","Cool 20 minutes, then refrigerate at least 30 minutes for the flavors to settle. Serve cool or at room temperature."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style / niche","seasonality":"Summer","tags":["Home-style / niche","Japan","Summer"],"photoQueries":["Aji nanbanzuke アジの南蛮漬け","Japanese fish nanbanzuke"],"auditStatus":"Reviewed 2026"},{"id":"jp_095","title":"Mizutaki","japaneseName":"水炊き","romanization":"mizutaki","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":45,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large donabe or heavy pot","ingredients":["700 g bone-in chicken pieces","1.5 L water","1 piece kombu, about 10 cm","1/2 napa cabbage, chopped","1 long negi, sliced diagonally","200 g firm tofu, cubed","150 g shiitake or shimeji mushrooms","100 g carrot, sliced","200 ml ponzu, for serving","4 tbsp grated daikon, optional","2 tbsp sliced scallion"],"steps":["Put chicken, water, and kombu in a pot. Warm slowly and remove the kombu just before the water boils.","Bring to a gentle simmer, skim carefully, and cook the chicken 25–30 minutes to make a light chicken broth.","Add firm vegetables first: carrot, negi, and thick cabbage stems. Simmer 5 minutes.","Add tofu, mushrooms, and cabbage leaves and simmer until just tender. Keep the broth relatively plain; mizutaki is seasoned at the table.","Serve chicken and vegetables in individual bowls with a little broth. Dip bites in ponzu with grated daikon and scallion.","After most solids are eaten, season the remaining broth lightly and add cooked rice or noodles if you want a traditional finishing course."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.japan.travel/en/destinations/kyushu/fukuoka/","https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Fukuoka / Kyushu","profile":"Regional favorite","seasonality":"Cool weather","tags":["Regional favorite","Fukuoka / Kyushu","Cool weather"],"photoQueries":["Mizutaki 水炊き Fukuoka hot pot","Japanese mizutaki"],"auditStatus":"Reviewed 2026"},{"id":"jp_096","title":"Motsunabe","japaneseName":"もつ鍋","romanization":"motsunabe","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large donabe or heavy pot","ingredients":["500 g cleaned beef small intestine or mixed beef offal, prepared for cooking","1/2 head cabbage, about 500 g, chopped","1 bunch garlic chives nira, about 120 g, cut into 5 cm lengths","2 cloves garlic, thinly sliced","1 dried red chili, sliced","1 L dashi or light beef stock","4 tbsp soy sauce","3 tbsp sake","2 tbsp mirin","1 tsp sugar","200 g firm tofu, optional","2 portions champon noodles, for finishing, optional"],"steps":["If the offal is not sold cleaned and ready to cook, follow the butcher or package directions for parboiling and cleaning; drain very well.","Combine dashi, soy sauce, sake, mirin, sugar, garlic, and chili in a hot-pot vessel and bring to a simmer.","Add the offal and simmer 8–10 minutes, skimming excess foam and fat.","Pile cabbage and tofu over the meat, cover, and cook until the cabbage collapses. Add nira on top and simmer another 2–3 minutes.","Serve bubbling hot. Make sure the offal is fully cooked and tender before eating.","After the solids are mostly eaten, add champon noodles to the remaining broth and simmer until tender for the finishing course."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.japan.travel/en/destinations/kyushu/fukuoka/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"medium","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Fukuoka","profile":"Regional favorite","seasonality":"Cool weather","tags":["Regional favorite","Fukuoka","Cool weather"],"photoQueries":["Motsunabe もつ鍋 Fukuoka","Fukuoka motsunabe hot pot"],"auditStatus":"Reviewed 2026"},{"id":"jp_097","title":"Ishikari Nabe","japaneseName":"石狩鍋","romanization":"ishikari nabe","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":30,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large donabe or heavy pot","ingredients":["600 g salmon fillet, skin on, cut into chunks","1/2 napa cabbage, chopped","2 medium potatoes, cut into chunks","1 medium onion, sliced","1 carrot, sliced","150 g shimeji mushrooms","200 g firm tofu, cubed","1.2 L kombu dashi","80 g miso","2 tbsp sake","1 tbsp mirin","20 g butter, optional","2 tbsp sliced scallion"],"steps":["Bring kombu dashi, sake, and mirin to a simmer. Add potatoes, carrot, and onion and cook 8–10 minutes.","Add salmon, cabbage stems, mushrooms, and tofu. Simmer gently until the salmon is just cooked and potatoes are tender, about 8 minutes.","Put miso in a bowl and loosen it with hot broth, then stir it back into the pot. Avoid a hard boil after adding miso.","Add cabbage leaves and cook 2–3 minutes. Taste and add more miso only if needed.","Finish with a small pat of butter if desired, a common Hokkaido-style addition, and top with scallion."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.japan.travel/en/destinations/hokkaido/hokkaido/","https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Hokkaido","profile":"Regional / traditional","seasonality":"Autumn / winter","tags":["Regional / traditional","Hokkaido","Autumn / winter"],"photoQueries":["Ishikari nabe 石狩鍋 Hokkaido","Hokkaido salmon hot pot Ishikari"],"auditStatus":"Reviewed 2026"},{"id":"jp_098","title":"Yudofu","japaneseName":"湯豆腐","romanization":"yudōfu","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"small donabe or saucepan","ingredients":["400 g silken or soft tofu, cut into large cubes","800 ml water","1 piece kombu, about 10 cm","100 g napa cabbage or mizuna, optional","100 g shimeji mushrooms, optional","100 ml ponzu, for serving","2 tbsp sliced scallion","1 tsp grated ginger","1 tbsp grated daikon, optional"],"steps":["Wipe the kombu and soak it in 800 ml water in the pot for 20 minutes if time allows.","Warm the kombu water slowly over low heat. Remove the kombu just before the water reaches a boil.","Add tofu and optional vegetables. Keep the liquid below a boil and warm gently 5–8 minutes; vigorous boiling can roughen delicate tofu.","Serve tofu and vegetables directly from the pot with ponzu, scallion, ginger, and grated daikon at the table."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kyoto association","profile":"Traditional / minimalist","seasonality":"Cool weather","tags":["Traditional / minimalist","Kyoto association","Cool weather"],"photoQueries":["Yudofu 湯豆腐 Japanese food","Yudofu Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_099","title":"Kiritanpo Nabe","japaneseName":"きりたんぽ鍋","romanization":"kiritanpo nabe","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":35,"total":70,"servings":5,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large pot, grill or skillet, sturdy spoon","ingredients":["800 g hot cooked Japanese short-grain rice","1/2 tsp salt","500 g chicken thigh, bite-size pieces","1.2 L chicken stock","120 g gobo burdock root, shaved or thinly sliced","100 g maitake mushrooms","150 g shirataki noodles, rinsed","2 long negi, sliced diagonally","100 g seri Japanese parsley or mitsuba","4 tbsp soy sauce","2 tbsp sake","1 tsp salt, plus more to taste"],"steps":["While the rice is hot, pound it with a sturdy spoon or pestle until about half the grains are mashed and the mixture becomes sticky. With damp salted hands, press rice around thick skewers or form elongated logs.","Grill or pan-sear the rice logs until lightly browned, then cool slightly and cut into 5–6 cm pieces.","Bring chicken stock to a simmer with chicken and gobo. Skim and cook 8–10 minutes.","Add shirataki and maitake, then season the broth with soy sauce, sake, and salt. Simmer 5 minutes.","Add kiritanpo and negi and simmer only 2–3 minutes so the rice does not disintegrate.","Finish with seri or mitsuba and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/2602/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Akita","profile":"Regional / niche","seasonality":"Autumn / winter","tags":["Regional / niche","Akita","Autumn / winter"],"photoQueries":["Kiritanpo nabe きりたんぽ鍋 Akita","Akita kiritanpo hot pot"],"auditStatus":"Reviewed 2026"},{"id":"jp_100","title":"Yamagata Imoni","japaneseName":"芋煮","romanization":"imoni","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":40,"total":60,"servings":5,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large pot","ingredients":["700 g satoimo taro, peeled and cut into chunks","250 g thinly sliced beef","250 g konnyaku, torn into pieces","1 long negi, thickly sliced","150 g shimeji mushrooms, optional","1.2 L water","5 tbsp soy sauce","3 tbsp sake","2 tbsp sugar","1 tbsp mirin"],"steps":["Parboil the taro for 3 minutes, drain, and rinse away excess surface foam. Briefly blanch the konnyaku and drain.","Put taro and 1.2 L water in a pot and simmer 10 minutes. Add konnyaku and mushrooms if using.","Add beef, separating the slices, and skim any foam that rises.","Season with soy sauce, sake, sugar, and mirin. Simmer gently until the taro is fully tender and the broth is savory-sweet, about 15–20 minutes.","Add negi for the final 3–4 minutes. Taste and adjust the balance of soy and sweetness before serving."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/553/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Yamagata","profile":"Regional / traditional","seasonality":"Autumn","tags":["Regional / traditional","Yamagata","Autumn"],"photoQueries":["Yamagata imoni 芋煮","Imoni Yamagata taro beef soup"],"auditStatus":"Reviewed 2026"},{"id":"jp_101","title":"Kanto-Style Ozoni","japaneseName":"お雑煮","romanization":"ozōni","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan, toaster or grill","ingredients":["4 rectangular kirimochi rice cakes","250 g boneless chicken thigh, bite-size pieces","1 L dashi","100 g daikon, cut into thin half-moons","80 g carrot, sliced","4 shiitake mushrooms, trimmed","1 tbsp soy sauce","1 tbsp sake","1 tsp salt","80 g spinach or komatsuna, blanched","4 slices kamaboko fish cake","4 sprigs mitsuba","4 strips yuzu peel, optional"],"steps":["Bring dashi to a simmer and add chicken, daikon, carrot, and shiitake. Skim and cook until the chicken is done and vegetables are tender, about 10–12 minutes.","Season the clear soup with soy sauce, sake, and salt; keep the flavor delicate.","Toast or grill the mochi until puffed and lightly browned. Handle carefully because the center becomes very hot and sticky.","Put one mochi in each bowl with blanched greens and kamaboko.","Pour over the hot soup with chicken and vegetables and garnish with mitsuba and yuzu peel. Serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kanto-style version","profile":"Seasonal / traditional","seasonality":"New Year","tags":["Seasonal / traditional","Kanto-style version","New Year"],"photoQueries":["Kanto ozoni お雑煮 Japanese New Year soup","Japanese ozoni mochi soup"],"auditStatus":"Reviewed 2026"},{"id":"jp_102","title":"Kenchinjiru","japaneseName":"けんちん汁","romanization":"kenchinjiru","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"yes","equipment":"large saucepan","ingredients":["250 g firm tofu, drained","100 g daikon, sliced","80 g carrot, sliced","80 g gobo burdock root, thinly sliced","100 g satoimo taro, peeled and halved","100 g konnyaku, torn into pieces","4 shiitake mushrooms, sliced","1 tbsp sesame oil","1 L kombu-shiitake dashi","2 tbsp soy sauce","1 tbsp sake","1 tsp salt","2 tbsp sliced scallion"],"steps":["Wrap tofu in paper towels and press 10 minutes. Parboil taro and konnyaku briefly, then drain.","Heat sesame oil in a pot. Add daikon, carrot, gobo, taro, konnyaku, and mushrooms and sauté 3–4 minutes.","Crumble tofu into large pieces and stir it through the vegetables.","Add dashi and sake. Simmer gently 15–18 minutes until the root vegetables are tender.","Season with soy sauce and salt. Simmer 2 minutes more, then serve with scallion."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Temple / home-style","seasonality":"All year","tags":["Temple / home-style","Japan","All year"],"photoQueries":["Kenchinjiru けんちん汁 Japanese food","Kenchinjiru Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_103","title":"Hijiki no Nimono","japaneseName":"ひじきの煮物","romanization":"hijiki no nimono","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"yes","equipment":"medium saucepan","ingredients":["20 g dried hijiki seaweed","1/2 carrot, julienned","1 sheet aburaage fried tofu, thinly sliced","80 g shelled edamame","1 tsp sesame oil","250 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar"],"steps":["Soak dried hijiki according to the package, usually 15–20 minutes, then rinse thoroughly and drain.","Pour hot water over the aburaage, blot, and slice. Heat sesame oil in a saucepan and sauté carrot and hijiki for 2 minutes.","Add aburaage, dashi, sake, sugar, mirin, and soy sauce. Bring to a gentle simmer.","Cook uncovered 12–15 minutes until the liquid is mostly absorbed but the hijiki remains moist.","Stir in edamame for the final 2 minutes. Cool slightly before serving; the flavor deepens as it rests."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Hijiki no Nimono ひじきの煮物 Japanese food","Hijiki no Nimono Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_104","title":"Kiriboshi Daikon no Nimono","japaneseName":"切り干し大根の煮物","romanization":"kiriboshi daikon no nimono","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"yes","equipment":"medium saucepan","ingredients":["40 g dried kiriboshi daikon","1/2 carrot, julienned","1 sheet aburaage fried tofu, thinly sliced","300 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","1 tbsp sake","1 tsp neutral oil"],"steps":["Rinse kiriboshi daikon and soak in cool water 15 minutes, or as directed on the package. Squeeze gently and cut long strands into easy-to-eat lengths.","Heat oil in a saucepan. Sauté the rehydrated daikon and carrot for 2 minutes.","Add aburaage, dashi, sake, sugar, mirin, and soy sauce. Bring to a simmer.","Cook uncovered over medium-low heat 12–15 minutes, stirring occasionally, until the vegetables are tender and most liquid is absorbed.","Rest 10 minutes before serving warm or at room temperature."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Kiriboshi Daikon no Nimono 切り干し大根の煮物 Japanese food","Kiriboshi Daikon no Nimono Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_105","title":"Nasu Agebitashi","japaneseName":"なすの揚げびたし","romanization":"nasu agebitashi","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":15,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep skillet or saucepan, shallow dish","ingredients":["4 Japanese eggplants, about 400 g","neutral oil, enough for shallow frying","250 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp grated ginger","2 tbsp grated daikon, optional","2 tbsp sliced scallion"],"steps":["Combine dashi, soy sauce, and mirin in a small saucepan, bring to a brief simmer, then pour into a shallow serving dish with half the ginger.","Trim eggplants, halve lengthwise, and score the skin shallowly at 5 mm intervals. Pat dry.","Heat about 1 cm oil over medium-high. Fry eggplant skin-side first, then turn, until tender and lightly browned. Drain briefly.","Put the eggplant directly into the warm dashi marinade and spoon liquid over it. Rest at least 15 minutes; chill if you prefer it cold.","Serve with remaining ginger, grated daikon, and scallion."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"Summer","tags":["Home-style","Japan","Summer"],"photoQueries":["Nasu Agebitashi なすの揚げびたし Japanese food","Nasu Agebitashi Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_106","title":"Koya Dofu no Nimono","japaneseName":"高野豆腐の煮物","romanization":"kōya dōfu no nimono","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":20,"total":30,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"yes","equipment":"medium saucepan","ingredients":["4 pieces koya-dofu freeze-dried tofu","500 ml dashi","2 tbsp sugar","2 tbsp mirin","1 1/2 tbsp usukuchi soy sauce or regular soy sauce","1 tbsp sake","80 g carrot, cut into decorative slices, optional","60 g snow peas, blanched"],"steps":["Rehydrate koya-dofu according to the package, then gently press out excess water without crushing it. Cut into halves if large.","Bring dashi, sugar, mirin, soy sauce, and sake to a gentle simmer. Add carrot if using and cook 3 minutes.","Add the tofu in a single layer. Cover with a drop lid or parchment and simmer very gently 12–15 minutes so it absorbs the broth evenly.","Turn off the heat and let the tofu stand in the cooking liquid 10 minutes.","Serve warm or room temperature with carrot and snow peas."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional / home-style","seasonality":"All year","tags":["Traditional / home-style","Japan","All year"],"photoQueries":["Koya Dofu no Nimono 高野豆腐の煮物 Japanese food","Koya Dofu no Nimono Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_107","title":"Shira-ae","japaneseName":"白和え","romanization":"shira-ae","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":10,"total":30,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, mortar or food processor","ingredients":["300 g firm tofu","150 g spinach","80 g carrot, julienned","80 g konnyaku, thinly sliced","2 tbsp toasted white sesame seeds","1 1/2 tbsp sugar","1 tbsp white miso","1 tsp soy sauce","1/4 tsp salt"],"steps":["Wrap tofu in paper towels and press under a light weight 15 minutes. Blanch spinach, cool, squeeze very dry, and cut into 4 cm lengths.","Blanch carrot and konnyaku 2–3 minutes until the carrot is just tender, then drain and cool completely.","Grind sesame seeds until fragrant. Add tofu, sugar, miso, soy sauce, and salt and mash to a creamy but slightly textured dressing.","Make sure the vegetables are dry, then fold them gently into the tofu dressing.","Chill briefly or serve at room temperature. Shira-ae is best the day it is made."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional / home-style","seasonality":"All year","tags":["Traditional / home-style","Japan","All year"],"photoQueries":["Shira-ae 白和え Japanese food","Shira-ae Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_108","title":"Hiyayakko","japaneseName":"冷奴","romanization":"hiyayakko","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":0,"total":10,"servings":2,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"serving plates","ingredients":["300 g chilled silken tofu","2 tbsp finely sliced scallion","1 tsp grated ginger","5 g katsuobushi bonito flakes","1 tbsp soy sauce","1 tsp toasted sesame seeds, optional"],"steps":["Keep tofu chilled until serving. Drain away package liquid and blot the outside very gently.","Cut tofu into two neat blocks and place on chilled plates.","Top each portion with scallion, ginger, katsuobushi, and sesame if using.","Drizzle soy sauce over immediately before eating rather than letting the tofu sit in it."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style / quick","seasonality":"All year","tags":["Home-style / quick","Japan","All year"],"photoQueries":["Hiyayakko 冷奴 Japanese food","Hiyayakko Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_109","title":"Japanese Potato Salad","japaneseName":"ポテトサラダ","romanization":"poteto sarada","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":55,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"medium pot, mixing bowl","ingredients":["500 g waxy or all-purpose potatoes, peeled and cut into chunks","1/2 carrot, thinly sliced","1/2 cucumber, very thinly sliced","1/4 small onion, very thinly sliced","80 g ham, cut into strips, optional","1 hard-boiled egg, chopped, optional","1 tsp rice vinegar","1/2 tsp salt, divided","80 g Japanese mayonnaise","1/4 tsp white pepper"],"steps":["Boil potatoes in salted water until completely tender. Add carrot for the final 3 minutes, then drain well.","Return potatoes to the warm pot for 30 seconds to steam off moisture. Mash roughly, leaving some small pieces, then season with rice vinegar while hot.","Sprinkle cucumber and onion with a pinch of salt, leave 10 minutes, then squeeze dry.","When the potatoes are warm rather than hot, fold in cucumber, onion, ham and egg if using.","Mix in mayonnaise and white pepper. Taste for salt, then chill at least 15 minutes before serving."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Yoshoku home-style","seasonality":"All year","tags":["Yoshoku home-style","Japan","All year"],"photoQueries":["Japanese Potato Salad ポテトサラダ Japanese food","Japanese Potato Salad Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_110","title":"Kinpira Renkon","japaneseName":"れんこんのきんぴら","romanization":"renkon no kinpira","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":22,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"large skillet","ingredients":["300 g lotus root, peeled","1 tsp rice vinegar, for soaking water","1 tbsp sesame oil","2 tbsp soy sauce","2 tbsp mirin","1 tsp sugar","1 dried red chili, sliced, optional","1 tbsp toasted sesame seeds"],"steps":["Slice lotus root into thin rounds or half-moons. Soak 5 minutes in water with rice vinegar, then drain and dry well.","Heat sesame oil in a skillet over medium-high. Add lotus root and stir-fry 3–4 minutes until the edges turn translucent.","Add soy sauce, mirin, sugar, and chili if using. Cook 3–4 minutes, tossing, until the liquid reduces to a light glaze while the lotus root stays crisp.","Turn off the heat and toss with sesame seeds. Serve warm or at room temperature."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style","seasonality":"All year","tags":["Home-style","Japan","All year"],"photoQueries":["Kinpira Renkon れんこんのきんぴら Japanese food","Kinpira Renkon Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_111","title":"Mitarashi Dango","japaneseName":"みたらし団子","romanization":"mitarashi dango","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan, bamboo skewers","ingredients":["100 g dangoko dumpling flour or equal parts joshinko and shiratamako","75–90 ml water","2 tbsp soy sauce","5 tbsp mirin","4 tbsp sugar","4 tbsp water for sauce","1 tbsp potato starch","1 tbsp water for starch slurry"],"steps":["Mix the dumpling flour with 75 ml water, adding a little more only as needed, and knead until soft and smooth like an earlobe. Divide into 16 balls.","Boil the dumplings in plenty of water. After they float, cook another 2–3 minutes, then transfer to cold water and drain.","Thread 4 dumplings onto each skewer. For a more traditional finish, lightly grill or dry-sear until a few browned spots appear.","Combine soy sauce, mirin, sugar, and 4 tbsp water in a saucepan. Boil briefly to cook off the mirin alcohol.","Stir the starch with 1 tbsp water, add gradually to the simmering sauce, and cook until glossy and thick enough to cling.","Coat the dango generously with warm sauce and serve."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.kikkoman.com/en/cookbook/recipe/00001609.html","https://www.kikkoman.com/en/cookbook/feature/soysaucedessertrecipes.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional sweet","seasonality":"All year","tags":["Traditional sweet","Japan","All year"],"photoQueries":["Mitarashi dango みたらし団子","Japanese mitarashi dango"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_112","title":"Hanami Dango","japaneseName":"花見団子","romanization":"hanami dango","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":15,"total":40,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan, bamboo skewers","ingredients":["120 g shiratamako glutinous rice flour","80 g joshinko rice flour","60 g sugar","150–170 ml warm water","1 tsp matcha","1 tsp strawberry powder or a tiny amount pink food coloring","6 bamboo skewers"],"steps":["Mix shiratamako, joshinko, and sugar. Gradually add warm water, kneading until a smooth soft dough forms.","Divide the dough into three equal portions. Leave one white, knead matcha into one, and strawberry powder or a tiny amount of pink coloring into the third.","Roll each color into 6 equal balls, for 18 dumplings total.","Boil the white dumplings first, then pink, then green, so the colors stay clean. After each batch floats, cook 2 minutes more and transfer to cold water.","Drain and blot dry. Thread one green, one white, and one pink dumpling onto each skewer in the traditional three-color arrangement."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Seasonal traditional sweet","seasonality":"Spring / cherry blossom season","tags":["Seasonal traditional sweet","Japan","Spring / cherry blossom season"],"photoQueries":["Hanami Dango 花見団子 Japanese food","Hanami Dango Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_113","title":"Sakura Mochi (Domyoji-Style)","japaneseName":"桜餅","romanization":"sakura mochi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":75,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer or microwave-safe bowl","ingredients":["200 g domyojiko coarse glutinous rice flour, or 200 g soaked and coarsely crushed glutinous rice","250 ml water","40 g sugar","1–2 drops pink food coloring, optional","240 g smooth anko red bean paste","8 salt-pickled sakura leaves"],"steps":["Rinse excess salt from the sakura leaves and soak them in fresh water 10–15 minutes, then pat dry. Divide anko into 8 small oval portions.","Mix domyojiko, water, sugar, and a tiny amount of pink coloring if using. Steam until the grains are translucent and tender, about 15–18 minutes, or microwave in covered intervals according to the flour package.","Cover the cooked rice mixture and rest 10 minutes so the moisture distributes evenly. Cool until safe to handle.","With damp hands divide into 8 portions. Flatten each into an oval, place anko in the center, and wrap the rice around it.","Wrap each mochi in a sakura leaf, vein side outward. Rest 10 minutes before serving so the leaf fragrance perfumes the mochi."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kansai / Domyoji style","profile":"Seasonal traditional sweet","seasonality":"Spring","tags":["Seasonal traditional sweet","Kansai / Domyoji style","Spring"],"photoQueries":["Sakura mochi 桜餅 Domyoji","Japanese sakura mochi"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_114","title":"Ohagi","japaneseName":"おはぎ","romanization":"ohagi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":70,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker or pot, mixing bowls","ingredients":["240 g Japanese glutinous rice","80 g Japanese short-grain rice","390 ml water","400 g smooth or chunky anko red bean paste","40 g kinako roasted soybean flour","25 g sugar","1/4 tsp salt"],"steps":["Rinse both rices together and cook with 390 ml water. Rest 10 minutes after cooking.","While hot, pound or mash the rice lightly until it becomes sticky but many grains remain visible. Divide into 8 portions with damp hands.","For anko-coated ohagi, flatten a portion of anko on plastic wrap, place rice in the center, and wrap the bean paste around it.","For kinako-coated ohagi, flatten rice, place a small spoonful of anko inside, seal, and shape into an oval.","Mix kinako with sugar and salt and roll the filled rice ovals in it. Serve the same day for the best texture."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional sweet","seasonality":"Spring / autumn equinox","tags":["Traditional sweet","Japan","Spring / autumn equinox"],"photoQueries":["Ohagi おはぎ Japanese food","Ohagi Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_115","title":"Yokan","japaneseName":"羊羹","romanization":"yōkan","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":135,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, loaf pan or container","ingredients":["400 g smooth koshian red bean paste","4 g kanten agar powder","300 ml water","80 g sugar","1/8 tsp salt"],"steps":["Rinse a loaf pan or small container with water and leave it damp; this helps unmolding later.","Whisk kanten into 300 ml water in a saucepan. Bring to a full boil while stirring, then boil gently 2 minutes so the agar dissolves completely.","Add sugar and stir until dissolved. Add koshian in several additions and whisk smooth.","Simmer 3–5 minutes over medium-low heat, stirring the bottom constantly, until the mixture is glossy and slightly thickened. Add salt.","Pour into the mold and cool to room temperature, then chill at least 2 hours until firm. Unmold and slice with a damp knife."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional wagashi","seasonality":"All year","tags":["Traditional wagashi","Japan","All year"],"photoQueries":["Yokan 羊羹 Japanese food","Yokan Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_116","title":"Anmitsu","japaneseName":"あんみつ","romanization":"anmitsu","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":10,"total":145,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, shallow container","ingredients":["4 g kanten agar powder","500 ml water","2 tbsp sugar","160 g anko red bean paste","8 small shiratama dumplings, cooked","1 small mandarin orange, segmented","1 kiwi, sliced","100 g canned peach, sliced","4 tbsp kuromitsu black sugar syrup"],"steps":["Whisk kanten into water and bring to a boil, stirring. Boil gently 2 minutes, then add sugar.","Pour into a shallow container, cool, and refrigerate until firm, about 2 hours.","Cut the kanten into 1.5 cm cubes. Prepare fruit and cooked shiratama and keep chilled.","Divide kanten among four bowls. Arrange anko, shiratama, and fruit in separate clusters over the jelly.","Drizzle with kuromitsu immediately before serving."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional café sweet","seasonality":"All year","tags":["Traditional café sweet","Japan","All year"],"photoQueries":["Anmitsu あんみつ Japanese food","Anmitsu Japanese food"],"dessertStyle":"Chilled & café","auditStatus":"Reviewed 2026"},{"id":"jp_117","title":"Zenzai","japaneseName":"ぜんざい","romanization":"zenzai","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":75,"total":85,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"medium saucepan, grill or toaster","ingredients":["200 g dried azuki beans","1.2 L water, plus more as needed","160 g sugar","1/4 tsp salt","4 kirimochi rice cakes"],"steps":["Rinse azuki. Cover generously with water, boil 2 minutes, drain, then add 1.2 L fresh water.","Simmer gently 50–60 minutes until the beans are completely tender, adding hot water as needed to keep them submerged.","Add sugar in 2–3 additions and simmer another 10 minutes. Add salt to sharpen the sweetness; the soup should remain pourable.","Toast the mochi until puffed and lightly browned.","Place one mochi in each bowl and ladle the hot sweet azuki soup over it. Serve carefully because mochi is very hot and sticky."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional sweet","seasonality":"Cool weather","tags":["Traditional sweet","Japan","Cool weather"],"photoQueries":["Zenzai ぜんざい Japanese food","Zenzai Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_118","title":"Imagawayaki","japaneseName":"今川焼き","romanization":"imagawayaki","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"imagawayaki pan, aebleskiver pan, or small ring molds","ingredients":["150 g cake flour","1 tsp baking powder","40 g sugar","1 large egg","180 ml milk","1 tsp honey","240 g anko red bean paste","1 tsp neutral oil"],"steps":["Sift flour and baking powder. Whisk sugar, egg, milk, and honey, then fold in the dry ingredients just until smooth. Rest 10 minutes.","Divide anko into 6 portions. Heat the special pan or ring molds over medium-low and brush very lightly with oil.","Fill each mold about halfway with batter. When bubbles appear and the edges start setting, place anko in the center.","Cover the filling with a little more batter. If using a two-sided pan, close or cap with another partly cooked half; otherwise cook slowly and turn carefully once stable.","Cook until both sides are evenly golden and the center batter is cooked through. Cool 3–4 minutes before eating."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","egg","dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Street sweet","seasonality":"All year","tags":["Street sweet","Japan","All year"],"photoQueries":["Imagawayaki 今川焼き Japanese sweet","Japanese imagawayaki red bean cake"],"dessertStyle":"Cakes & griddled","auditStatus":"Reviewed 2026"},{"id":"jp_119","title":"Melon Pan","japaneseName":"メロンパン","romanization":"meron pan","category":"Breads & Pastries","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":18,"total":130,"servings":8,"difficulty":"Hard","energy":"high","cleanup":2,"freezer":"no","equipment":"stand mixer optional, baking tray","ingredients":["250 g bread flour","30 g sugar","4 g instant yeast","4 g salt","1 large egg, beaten","120 ml warm milk","30 g unsalted butter, softened","120 g cake flour for cookie crust","50 g unsalted butter for cookie crust","60 g sugar for cookie crust","1/2 beaten egg, about 25 g, for cookie crust","1/2 tsp vanilla extract","2 tbsp granulated sugar, for coating"],"steps":["For the bread dough, mix bread flour, sugar, yeast, salt, egg, and milk. Knead until elastic, then knead in 30 g butter until smooth. Cover and rise until doubled, about 60 minutes.","For the cookie crust, cream 50 g butter and 60 g sugar. Beat in 1/2 egg and vanilla, then mix in cake flour. Divide into 8 disks and chill 20 minutes.","Deflate the risen bread dough gently, divide into 8 pieces, round, and rest 10 minutes.","Flatten each chilled cookie disk between plastic, wrap it over the top of a bread ball, leaving the bottom exposed, and dip the crust in granulated sugar.","Score a shallow diamond pattern across the cookie layer without cutting into the bread. Proof 25–30 minutes until puffy.","Bake at 180°C for 15–18 minutes until the cookie crust is lightly golden. Cool on a rack."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","egg","dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Popular bakery","seasonality":"All year","tags":["Popular bakery","Japan","All year"],"photoQueries":["Melon pan メロンパン Japanese bread","Japanese melonpan"],"auditStatus":"Reviewed 2026"},{"id":"jp_120","title":"Anpan","japaneseName":"あんパン","romanization":"anpan","category":"Breads & Pastries","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":18,"total":125,"servings":8,"difficulty":"Medium","energy":"high","cleanup":2,"freezer":"no","equipment":"stand mixer optional, baking tray","ingredients":["250 g bread flour","30 g sugar","4 g instant yeast","4 g salt","1 large egg, beaten","120 ml warm milk","30 g unsalted butter, softened","320 g anko red bean paste","1 tbsp black sesame seeds","1 tbsp beaten egg or milk, for glazing"],"steps":["Mix bread flour, sugar, yeast, salt, egg, and milk and knead until elastic. Knead in butter and continue until smooth. Cover and rise until doubled, about 60 minutes.","Divide anko into 8 balls of about 40 g. Divide the dough into 8 equal pieces, round, and rest 10 minutes.","Flatten each dough piece, place anko in the center, and pinch the seam completely closed. Put seam-side down on a lined tray and flatten very slightly.","Proof 25–30 minutes until noticeably puffy. Brush lightly with beaten egg or milk and sprinkle black sesame in the center.","Bake at 180°C for 15–18 minutes until evenly golden. Cool at least 10 minutes before eating because the bean paste retains heat."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","egg","dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Popular bakery","seasonality":"All year","tags":["Popular bakery","Japan","All year"],"photoQueries":["Anpan あんパン Japanese food","Anpan Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_121","title":"Japanese Coffee Jelly","japaneseName":"コーヒーゼリー","romanization":"kōhī zerī","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":5,"total":135,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"small saucepan, 4 glasses or one container","ingredients":["500 ml strong brewed coffee","45 g sugar","8 g powdered gelatin","3 tbsp cool water","80 ml heavy cream or milk, for serving","2 tbsp simple syrup, optional"],"steps":["Sprinkle gelatin over 3 tbsp cool water and leave 5 minutes to bloom.","While the coffee is hot, stir in sugar until dissolved. Add bloomed gelatin and stir until completely melted; do not boil the gelatin.","Pour into four glasses or a shallow container. Cool, then refrigerate at least 2 hours until fully set.","Serve in the glasses or cut/scoop the jelly into cubes.","Pour a little cream or milk over each portion and add syrup only if you want it sweeter."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Kissaten café sweet","seasonality":"All year","tags":["Kissaten café sweet","Japan","All year"],"photoQueries":["Japanese Coffee Jelly コーヒーゼリー Japanese food","Japanese Coffee Jelly Japanese food"],"dessertStyle":"Chilled & café","auditStatus":"Reviewed 2026"},{"id":"jp_122","title":"Zunda Mochi","japaneseName":"ずんだ餅","romanization":"zunda mochi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":10,"total":30,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan, mortar or food processor","ingredients":["600 g edamame in pods, or about 250 g shelled edamame","60 g sugar","1/4 tsp salt","8 small mochi rice cakes","2–4 tbsp warm water, as needed"],"steps":["Boil edamame until tender, then shell them. For the smoothest zunda, pinch off the thin skins while the beans are still warm.","Pound or process the beans to a coarse paste; zunda traditionally retains a little texture rather than becoming completely smooth.","Mix in sugar and salt. Add warm water a spoonful at a time until the paste is soft enough to coat mochi.","Warm or soften the mochi according to its package until tender and stretchy.","Coat the warm mochi generously with zunda paste and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/1153/index.html","https://www.maff.go.jp/e/policies/market/dento_syoku/menu/zunda.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Miyagi / Tohoku","profile":"Regional traditional sweet","seasonality":"Summer","tags":["Regional traditional sweet","Miyagi / Tohoku","Summer"],"photoQueries":["Zunda mochi ずんだ餅 Miyagi","Miyagi zunda mochi"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_123","title":"Nama Yatsuhashi","japaneseName":"生八ツ橋","romanization":"nama yatsuhashi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":8,"total":33,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"microwave-safe bowl or steamer, rolling pin","ingredients":["100 g shiratamako glutinous rice flour","60 g joshinko rice flour","70 g sugar","180 ml water","2 tsp ground cinnamon","160 g smooth anko red bean paste","20 g kinako roasted soybean flour, for dusting"],"steps":["Whisk shiratamako, joshinko, sugar, and water until no dry lumps remain.","Steam the mixture until translucent and sticky, about 12–15 minutes, or microwave covered in 1-minute intervals, stirring between intervals, until fully cooked.","Dust a work surface generously with kinako mixed with cinnamon. Turn out the hot dough and dust the top as well.","When safe to handle, roll the dough very thin, about 2 mm, adding more kinako mixture to prevent sticking.","Cut into 8–10 cm squares. Put a small mound of anko in each center and fold diagonally into triangles, pressing lightly around the filling.","Serve the same day for the softest texture."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kyoto","profile":"Regional wagashi","seasonality":"All year","tags":["Regional wagashi","Kyoto","All year"],"photoQueries":["Nama yatsuhashi 生八ツ橋 Kyoto","Kyoto yatsuhashi sweet"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_124","title":"Mugicha","japaneseName":"麦茶","romanization":"mugicha","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":2,"cook":10,"total":70,"servings":6,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"kettle or saucepan, heatproof pitcher","ingredients":["2 L water","20 g roasted barley tea, loose or in 1 large mugicha tea bag","ice, as needed for serving"],"steps":["Bring 2 L water to a boil. Add roasted barley tea or the tea bag.","For a full-flavored boiled version, simmer 3–5 minutes, then turn off the heat and steep another 5 minutes.","Remove or strain the barley promptly so the drink does not become overly bitter.","Cool the tea to room temperature, then refrigerate until cold.","Serve over ice. Refrigerate and use within about 2 days for the freshest flavor."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Everyday drink","seasonality":"Especially summer","tags":["Everyday drink","Japan","Especially summer"],"photoQueries":["Mugicha 麦茶 Japanese barley tea","Japanese mugicha iced barley tea"],"drinkStyle":"Tea","auditStatus":"Reviewed 2026"},{"id":"jp_125","title":"Hojicha Latte","japaneseName":"ほうじ茶ラテ","romanization":"hōjicha rate","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":5,"total":10,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"small saucepan, fine strainer or whisk","ingredients":["12 g loose hojicha tea leaves, or 4 tea bags","180 ml freshly boiled water","300 ml milk or unsweetened soy milk","1–2 tbsp sugar or honey, to taste"],"steps":["Steep hojicha in 180 ml freshly boiled water for 3–4 minutes to make a concentrated tea, then strain.","Warm milk in a saucepan until steaming but not boiling. Sweeten to taste.","Divide the concentrated hojicha between two mugs and pour in the hot milk.","Whisk or froth briefly if desired and serve immediately."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Modern café drink","seasonality":"All year","tags":["Modern café drink","Japan","All year"],"photoQueries":["Hojicha latte ほうじ茶ラテ Japanese","Japanese hojicha latte"],"drinkStyle":"Tea","auditStatus":"Reviewed 2026"},{"id":"jp_126","title":"Matcha Latte","japaneseName":"抹茶ラテ","romanization":"matcha rate","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":5,"total":10,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"tea bowl or small bowl, bamboo whisk or regular whisk","ingredients":["4 g culinary or latte-grade matcha, about 2 tsp","60 ml hot water, about 80°C","300 ml milk or unsweetened soy milk","1–2 tbsp sugar or honey, to taste"],"steps":["Sift matcha into a bowl so no dry lumps remain.","Add 60 ml hot, not boiling, water and whisk briskly until completely smooth and lightly foamy.","Warm milk until steaming and sweeten to taste. Froth if desired.","Divide matcha between two cups and pour in the milk, stirring once before drinking."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.kikkoman.com/en/culture/foodforum/the-japanese-table/33-1.html","https://www.kikkoman.com/en/culture/foodforum/the-japanese-table/33-4.html"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Modern café drink","seasonality":"All year","tags":["Modern café drink","Japan","All year"],"photoQueries":["Matcha latte 抹茶ラテ Japanese","Japanese matcha latte"],"drinkStyle":"Tea","auditStatus":"Reviewed 2026"},{"id":"jp_127","title":"Japanese Royal Milk Tea","japaneseName":"ロイヤルミルクティー","romanization":"roiyaru miruku tī","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":8,"total":13,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":1,"freezer":"no","equipment":"small saucepan, fine strainer","ingredients":["250 ml water","10 g strong black tea leaves, such as Assam or Ceylon","250 ml whole milk","1–2 tbsp sugar, to taste"],"steps":["Bring water just to a boil in a small saucepan. Add tea leaves, lower the heat, and simmer very gently for 1 minute.","Add milk and warm slowly, stirring occasionally. Stop before the mixture reaches a rolling boil.","Turn off the heat and steep 2 minutes for a strong, rounded tea flavor.","Strain into cups and sweeten to taste. Serve hot."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Kissaten / café drink","seasonality":"All year","tags":["Kissaten / café drink","Japan","All year"],"photoQueries":["Japanese royal milk tea ロイヤルミルクティー","Royal milk tea Japan"],"drinkStyle":"Café","auditStatus":"Reviewed 2026"},{"id":"jp_128","title":"Koji Amazake","japaneseName":"米麹甘酒","romanization":"kome-kōji amazake","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":480,"total":490,"servings":6,"difficulty":"Medium","energy":"low","cleanup":2,"freezer":"no","equipment":"rice cooker with warm setting or temperature-controlled cooker, thermometer","ingredients":["200 g rice koji","200 g hot cooked Japanese rice","600 ml water","pinch of salt, optional","grated ginger, optional for serving"],"steps":["Break the rice koji apart so there are no large clumps. Mix hot cooked rice with 400 ml water and cool the mixture to about 60°C.","Stir in the koji, then add enough of the remaining water to make a loose porridge. Keep the mixture between about 55–60°C; higher heat can damage the enzymes.","Hold at that temperature for 6–8 hours, stirring every 1–2 hours. A rice cooker on warm with the lid ajar and a towel over the top can work, but check the temperature regularly.","Taste after 6 hours. When distinctly sweet with soft grains, the amazake is ready. For a smoother drink, blend briefly.","Heat to steaming if serving hot, or cool promptly and refrigerate. Thin with water to taste and add ginger if desired."],"notes":"A researched practical home-cooking version. Seasoning and presentation can vary by household and region.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional fermented drink","seasonality":"All year","tags":["Traditional fermented drink","Japan","All year"],"photoQueries":["Kome koji amazake 米麹甘酒","Japanese koji amazake"],"drinkStyle":"Traditional","auditStatus":"Reviewed 2026"},{"id":"jp_129","title":"Mizu Yokan","japaneseName":"水ようかん","romanization":"mizu yōkan","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":150,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, shallow mold","ingredients":["400 g smooth koshian red bean paste","500 ml water","4 g kanten agar powder","70 g sugar","1/8 tsp salt"],"steps":["Wet a shallow mold and set it aside. Whisk the kanten into the water in a saucepan before heating.","Bring to a full boil while stirring, then boil gently for 2 minutes so the agar fully dissolves.","Add sugar and stir until clear. Add the koshian in several additions, whisking until completely smooth, then add the salt.","Bring the mixture just back to a gentle simmer, stirring the bottom so it does not catch, then remove from the heat.","Cool for several minutes while stirring occasionally so the bean paste stays evenly suspended. Pour into the mold.","Cool to room temperature, then refrigerate at least 2 hours. Slice and serve well chilled."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/7458/index.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan / regional variations","profile":"Traditional wagashi","seasonality":"Summer","tags":["Traditional wagashi","Japan / regional variations","Summer"],"photoQueries":["Mizu Yokan 水ようかん Japanese food","Mizu Yokan Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_130","title":"Imo Yokan","japaneseName":"芋ようかん","romanization":"imo yōkan","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":30,"total":105,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer or saucepan, loaf pan, potato masher","ingredients":["600 g Japanese sweet potato, peeled","80 g sugar","1/4 tsp salt","2 tbsp water, only if needed"],"steps":["Cut the sweet potato into even chunks and soak in water for 10 minutes to remove excess surface starch.","Steam until completely tender, about 20–25 minutes. Drain away condensation and mash while hot.","Pass through a sieve for the smoothest texture, or mash very thoroughly for a more rustic finish.","Add sugar and salt while the potato is still hot. Mix firmly until glossy and cohesive; add water only a teaspoon at a time if the mixture is too dry to press.","Pack tightly into a parchment-lined loaf pan, smoothing the surface and pressing out air pockets.","Cool, then refrigerate about 1 hour until firm enough to slice cleanly."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/pref/tokyo/index.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Tokyo","profile":"Regional traditional sweet","seasonality":"Autumn / winter","tags":["Regional traditional sweet","Tokyo","Autumn / winter"],"photoQueries":["Imo Yokan 芋ようかん Japanese food","Imo Yokan Japanese food"],"dessertStyle":"Regional sweets","auditStatus":"Reviewed 2026"},{"id":"jp_131","title":"Yamaguchi Uiro","japaneseName":"外郎","romanization":"uirō","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":30,"total":75,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer, heatproof rectangular mold","ingredients":["120 g warabi starch or sweet-potato starch","40 g all-purpose flour","90 g sugar","350 ml water","120 g smooth koshian red bean paste"],"steps":["Whisk the starch, flour, sugar, and water until completely smooth. Strain into a saucepan.","Cook over low heat, stirring constantly, until the mixture thickens slightly but is still pourable.","Whisk in the koshian until the color and texture are even.","Pour into a lightly wet heatproof mold and tap gently to release large bubbles.","Steam over steady medium heat for about 25–30 minutes, covering the lid with a cloth so condensation does not drip onto the surface.","Cool completely before unmolding. Slice with a wet knife for clean edges."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/pref/yamaguchi/index.html"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Yamaguchi","profile":"Regional traditional sweet","seasonality":"All year","tags":["Regional traditional sweet","Yamaguchi","All year"],"photoQueries":["Yamaguchi uiro 外郎 Japanese sweet","Uiro Yamaguchi wagashi"],"dessertStyle":"Regional sweets","auditStatus":"Reviewed 2026"},{"id":"jp_132","title":"Sasa Dango","japaneseName":"笹団子","romanization":"sasa dango","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":40,"cook":25,"total":125,"servings":8,"difficulty":"Hard","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer, kitchen twine","ingredients":["220 g joshinko rice flour","80 g shiratamako glutinous rice flour","35 g sugar","15 g dried yomogi mugwort, rehydrated and squeezed dry","200–230 ml warm water","240 g anko red bean paste","24 food-safe bamboo leaves, rinsed and softened","8 lengths kitchen twine"],"steps":["Soak or blanch the bamboo leaves until flexible, then wipe them clean. Divide the anko into 8 portions.","Mix joshinko, shiratamako, sugar, and chopped rehydrated yomogi. Gradually add warm water and knead into a smooth, pliable dough.","Divide into 8 pieces. Flatten one piece in your palm, place anko in the center, seal, and shape into a short oval. Repeat.","Overlap three bamboo leaves for each dumpling, place the dumpling in the center, wrap securely, and tie with twine.","Arrange in a steamer with space between parcels and steam 20–25 minutes over steady steam.","Cool until comfortable to handle. The dumplings can be eaten warm or at room temperature; re-steam briefly if they firm up later."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/1586/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Niigata","profile":"Regional / niche wagashi","seasonality":"Spring / early summer","tags":["Regional / niche wagashi","Niigata","Spring / early summer"],"photoQueries":["Sasa Dango 笹団子 Japanese food","Sasa Dango Japanese food"],"dessertStyle":"Regional sweets","auditStatus":"Reviewed 2026"},{"id":"jp_133","title":"Ikinari Dango","japaneseName":"いきなり団子","romanization":"ikinari dango","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer","ingredients":["300 g Japanese sweet potato","160 g all-purpose flour","40 g shiratamako glutinous rice flour","1 tbsp sugar","1/2 tsp salt","130–150 ml water","200 g anko red bean paste"],"steps":["Peel the sweet potato and cut into eight rounds about 1 cm thick. Soak in cool water for 10 minutes, then drain and pat dry.","Mix flour, shiratamako, sugar, and salt. Add water gradually and knead until smooth and supple. Rest covered for 10 minutes.","Divide dough and anko into 8 portions. Place a portion of anko on each sweet-potato slice.","Flatten a piece of dough into a circle large enough to wrap the sweet potato and bean paste. Seal underneath and repeat.","Place seam-side down in a lined steamer and steam 20–25 minutes, until the sweet potato is tender and the wrapper is cooked through.","Rest 5 minutes before eating; the sweet-potato center stays very hot."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/287/index.html","https://www.maff.go.jp/e/policies/market/dento_syoku/menu/ikinari_dango.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kumamoto","profile":"Regional traditional sweet","seasonality":"Autumn","tags":["Regional traditional sweet","Kumamoto","Autumn"],"photoQueries":["Ikinari Dango いきなり団子 Japanese food","Ikinari Dango Japanese food"],"dessertStyle":"Regional sweets","auditStatus":"Reviewed 2026"},{"id":"jp_134","title":"Kuzukiri","japaneseName":"葛切り","romanization":"kuzukiri","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":15,"total":45,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, shallow heatproof tray, ice bath","ingredients":["80 g hon-kuzu starch","240 ml water","80 ml kuromitsu black sugar syrup","ice water, for chilling"],"steps":["Whisk kuzu starch with water until no dry lumps remain, then strain.","Pour a thin layer into a shallow heatproof tray. Float or hold the tray over simmering water until the surface turns translucent.","Dip the tray briefly into the hot water so the sheet finishes setting, then transfer immediately to an ice bath.","Peel the translucent sheet from the tray and cut into long noodle-like strips. Repeat with the remaining mixture.","Keep the kuzukiri in ice water until serving, then drain very well.","Serve chilled with kuromitsu on the side for dipping or drizzling."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kyoto association","profile":"Traditional wagashi","seasonality":"Summer","tags":["Traditional wagashi","Kyoto association","Summer"],"photoQueries":["Kuzukiri 葛切り Japanese dessert","Kyoto kuzukiri"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_135","title":"Suama","japaneseName":"すあま","romanization":"suama","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":50,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer, mixing bowl, rolling mat optional","ingredients":["200 g joshinko rice flour","90 g sugar","190 ml hot water","1 tiny drop pink food coloring, optional","20 g potato starch, for dusting"],"steps":["Mix joshinko and sugar. Gradually add hot water while stirring, then knead when cool enough to handle until evenly hydrated.","Steam the dough for about 15 minutes until cooked through and slightly translucent.","Transfer to a lightly starched surface and knead carefully while warm until smooth and elastic.","Leave half white and knead a tiny amount of pink coloring into the other half if making the traditional two-color version.","Shape into logs, or press gently with a rolling mat for a ridged surface. Cool completely.","Slice with a lightly dampened knife. Store tightly covered and eat while soft."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Kanto","profile":"Traditional wagashi","seasonality":"All year","tags":["Traditional wagashi","Kanto","All year"],"photoQueries":["Suama すあま Japanese food","Suama Japanese food"],"dessertStyle":"Wagashi & mochi","auditStatus":"Reviewed 2026"},{"id":"jp_136","title":"Oni Manju","japaneseName":"鬼まんじゅう","romanization":"oni manjū","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer, parchment squares","ingredients":["350 g Japanese sweet potato, scrubbed","100 g sugar","130 g all-purpose flour","20 g rice flour","1/4 tsp salt","60–80 ml water"],"steps":["Cut the sweet potato into 1 cm cubes, leaving some peel on for color if desired. Toss with sugar and leave 10 minutes until moisture draws out.","Mix flour, rice flour, and salt. Add to the sweet potato and toss, then add only enough water to create a thick batter that coats and binds the cubes.","Spoon eight rough mounds onto individual parchment squares, keeping the sweet-potato cubes visible on top.","Steam over strong, steady steam for about 18–20 minutes until the sweet potato is tender and the flour mixture is fully cooked.","Cool for several minutes before serving. Oni manju is good warm or at room temperature."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/442/index.html"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":["gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Aichi / Nagoya","profile":"Regional home-style sweet","seasonality":"Autumn","tags":["Regional home-style sweet","Aichi / Nagoya","Autumn"],"photoQueries":["Oni Manju 鬼まんじゅう Japanese food","Oni Manju Japanese food"],"dessertStyle":"Regional sweets","auditStatus":"Reviewed 2026"},{"id":"jp_137","title":"Usucha Matcha","japaneseName":"薄茶","romanization":"usucha","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":0,"total":5,"servings":1,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"matcha bowl, fine sieve, bamboo whisk or small whisk","ingredients":["2 g matcha powder","70 ml water at about 75–80°C"],"steps":["Warm the bowl with hot water, then empty and dry it thoroughly.","Sift matcha into the bowl so it is free of clumps.","Pour in 70 ml hot water; avoid freshly boiling water, which can make the tea harsh.","Whisk briskly in a loose M or W motion until a fine foam forms across the surface.","Drink immediately before the foam collapses and the matcha settles."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Traditional tea","seasonality":"All year","tags":["Traditional tea","Japan","All year"],"photoQueries":["Usucha Matcha 薄茶 Japanese food","Usucha Matcha Japanese food"],"drinkStyle":"Tea","auditStatus":"Reviewed 2026"},{"id":"jp_138","title":"Genmaicha","japaneseName":"玄米茶","romanization":"genmaicha","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":3,"cook":2,"total":5,"servings":2,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"teapot and strainer","ingredients":["8 g genmaicha tea leaves","400 ml water at about 85–90°C"],"steps":["Warm the teapot with a little hot water, then discard it.","Add genmaicha leaves and pour in 400 ml water at about 85–90°C.","Steep about 60–90 seconds; longer brewing can make the green-tea component bitter.","Pour all the tea out between the cups so the strength stays even. Serve immediately."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Everyday tea","seasonality":"All year","tags":["Everyday tea","Japan","All year"],"photoQueries":["Genmaicha 玄米茶 Japanese food","Genmaicha Japanese food"],"drinkStyle":"Tea","auditStatus":"Reviewed 2026"},{"id":"jp_139","title":"Melon Cream Soda","japaneseName":"メロンクリームソーダ","romanization":"meron kurīmu sōda","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":0,"total":5,"servings":1,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"tall glass","ingredients":["180 ml chilled melon soda","1 scoop vanilla ice cream","4–5 ice cubes","1 maraschino cherry, optional"],"steps":["Fill a tall glass with ice. Pour in the chilled melon soda, leaving several centimeters of space at the top.","Wait a few seconds for the foam to settle.","Gently place a scoop of vanilla ice cream on top so it floats above the soda rather than sinking immediately.","Add a cherry if desired and serve at once with a straw and long spoon."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japanese café culture","profile":"Kissaten café drink","seasonality":"All year","tags":["Kissaten café drink","Japanese café culture","All year"],"photoQueries":["Japanese melon cream soda メロンクリームソーダ","Japan kissaten melon cream soda"],"drinkStyle":"Café","auditStatus":"Reviewed 2026"},{"id":"jp_140","title":"Japanese Flash-Brew Iced Coffee","japaneseName":"急冷式アイスコーヒー","romanization":"kyūrei-shiki aisu kōhī","category":"Drinks","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":8,"cook":4,"total":12,"servings":2,"difficulty":"Medium","energy":"low","cleanup":1,"freezer":"no","equipment":"pour-over dripper, paper filter, server, scale","ingredients":["30 g medium-fine ground coffee","180 g ice","300 g hot water at about 92–96°C"],"steps":["Put 180 g ice in the serving carafe. Rinse the paper filter with hot water separately so the rinse water does not melt the measured ice.","Add coffee grounds and level the bed. Pour about 60 g hot water over the grounds and wait 30–40 seconds for the bloom.","Continue pouring slowly in controlled pulses until 300 g hot water has passed through the coffee.","Swirl the carafe until most of the measured ice melts and the coffee is evenly chilled.","Pour over fresh ice if desired and serve immediately."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegan","vegetarian"],"allergens":[],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japanese iced-coffee method","profile":"Kissaten / modern Japanese coffee","seasonality":"All year","tags":["Kissaten / modern Japanese coffee","Japanese iced-coffee method","All year"],"photoQueries":["Japanese Flash-Brew Iced Coffee 急冷式アイスコーヒー Japanese food","Japanese Flash-Brew Iced Coffee Japanese food"],"drinkStyle":"Café","auditStatus":"Reviewed 2026"},{"id":"jp_141","title":"Tamago Kake Gohan","japaneseName":"卵かけご飯","romanization":"tamago kake gohan","category":"Breakfast","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":0,"total":5,"servings":1,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"rice bowl","ingredients":["180 g piping-hot cooked Japanese short-grain rice","1 pasteurized egg or egg specifically produced for raw consumption","1–2 tsp soy sauce","1 tsp sliced scallion, optional","1/4 sheet nori, shredded, optional"],"steps":["Put piping-hot rice in a clean bowl.","Crack the safely handled egg into a separate small bowl first so you can check it before adding.","Make a shallow well in the rice and add the egg.","Add soy sauce and stir until the egg lightly coats and glosses the hot rice.","Top with scallion or nori if desired and eat immediately. Do not use ordinary eggs if raw-egg consumption is not considered safe where you live."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style breakfast","seasonality":"All year","tags":["Home-style breakfast","Japan","All year"],"photoQueries":["Tamago Kake Gohan 卵かけご飯 Japanese food","Tamago Kake Gohan Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_142","title":"Natto Gohan","japaneseName":"納豆ご飯","romanization":"nattō gohan","category":"Breakfast","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":5,"cook":0,"total":5,"servings":1,"difficulty":"Easy","energy":"low","cleanup":1,"freezer":"no","equipment":"small bowl and rice bowl","ingredients":["180 g hot cooked Japanese short-grain rice","1 pack natto, about 40–50 g","1 tsp soy sauce or the seasoning included with natto","1 tsp Japanese mustard, optional","1 tbsp sliced scallion","1/4 sheet nori, shredded, optional"],"steps":["Put natto in a small bowl and stir vigorously 30–45 seconds until noticeably sticky and aerated.","Mix in soy sauce or the included tare and mustard if using.","Put hot rice in a bowl and spoon the seasoned natto over the center.","Top with scallion and nori and serve immediately."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":["vegetarian"],"allergens":["soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Home-style breakfast","seasonality":"All year","tags":["Home-style breakfast","Japan","All year"],"photoQueries":["Natto Gohan 納豆ご飯 Japanese food","Natto Gohan Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_143","title":"Japanese Tamago Sando","japaneseName":"たまごサンド","romanization":"tamago sando","category":"Breakfast","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":12,"total":27,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan, mixing bowl","ingredients":["4 large eggs","4 slices Japanese milk bread or soft white sandwich bread","45 g Japanese mayonnaise","1 tsp milk","1/4 tsp salt","pinch white pepper","10 g softened butter"],"steps":["Boil the eggs for about 10 minutes for fully set yolks, then cool in ice water and peel.","Separate one yolk if you want an especially smooth filling. Roughly chop the remaining eggs.","Mash the yolks with mayonnaise, milk, salt, and white pepper, then fold in the chopped egg whites and remaining egg.","Lightly butter one side of each bread slice; this helps keep the sandwich tender without becoming soggy.","Spread the egg filling generously over two slices and close with the remaining bread.","Trim crusts if desired, cut each sandwich in half, and serve promptly or keep chilled until eating."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Convenience-store / home-style","seasonality":"All year","tags":["Convenience-store / home-style","Japan","All year"],"photoQueries":["Japanese Tamago Sando たまごサンド Japanese food","Japanese Tamago Sando Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_144","title":"Japanese Fruit Sando","japaneseName":"フルーツサンド","romanization":"furūtsu sando","category":"Breakfast","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":0,"total":80,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"mixing bowl, hand mixer optional","ingredients":["4 slices Japanese milk bread or soft white sandwich bread","180 ml cold heavy cream","18 g sugar","4 medium strawberries, hulled","1 kiwi, peeled","1/2 seedless orange or mandarin, peeled and dried"],"steps":["Dry all fruit very well so it does not make the cream watery. Cut large fruit into pieces that will create attractive cross-sections when sliced.","Whip cold cream with sugar to medium-firm peaks that hold their shape but are not grainy.","Spread a layer of cream over two bread slices. Arrange the fruit in a deliberate line where you plan to cut each sandwich.","Cover the fruit completely with more whipped cream, filling gaps so the sandwich holds together.","Top with the remaining bread, wrap tightly, mark the intended cutting direction on the wrap, and chill for about 1 hour.","Slice through the marked direction with a clean sharp knife, wiping the blade between cuts. Serve chilled."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","dairy"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Japan","profile":"Café / convenience-store favorite","seasonality":"All year","tags":["Café / convenience-store favorite","Japan","All year"],"photoQueries":["Japanese Fruit Sando フルーツサンド Japanese food","Japanese Fruit Sando Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_145","title":"Oita Tori-Ten","japaneseName":"とり天","romanization":"tori-ten","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep saucepan or fryer, rack","ingredients":["600 g boneless chicken thigh or breast, bite-size pieces","1 tbsp soy sauce","1 tbsp sake","1 tsp grated ginger","1 clove garlic, grated","1 large egg","100 ml ice-cold water","90 g all-purpose flour","30 g potato starch","neutral oil for deep-frying","ponzu and Japanese mustard, for serving"],"steps":["Mix chicken with soy sauce, sake, ginger, and garlic and marinate 10–15 minutes. Drain off excess liquid before battering.","Heat frying oil to about 170°C. Whisk egg with ice-cold water, then add flour and potato starch and mix only until barely combined.","Dip chicken pieces into the loose batter and lower them into the oil in small batches.","Fry about 3–5 minutes depending on size, turning as needed, until the coating is pale-crisp and the chicken is completely cooked.","Drain on a rack rather than paper towels so the batter stays crisp.","Serve immediately with ponzu and a small amount of Japanese mustard."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/4996/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten","egg"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Oita","profile":"Regional favorite","seasonality":"All year","tags":["Regional favorite","Oita","All year"],"photoQueries":["Oita Tori-Ten とり天 Japanese food","Oita Tori-Ten Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_146","title":"Niigata Noppe","japaneseName":"のっぺ","romanization":"noppe","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":35,"total":60,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large saucepan","ingredients":["500 g satoimo taro, peeled and cut into chunks","100 g carrot, cut into small decorative or half-moon pieces","120 g konnyaku, torn or cut","100 g bamboo shoots, sliced","4 dried shiitake mushrooms, soaked and sliced","80 g kamaboko or chikuwa, sliced","150 g cooked chicken thigh or salted salmon, bite-size pieces","800 ml dashi, including shiitake soaking liquid if clean","2 tbsp usukuchi soy sauce or regular soy sauce","2 tbsp sake","1 tbsp mirin","1/2 tsp salt","80 g snow peas or green beans, blanched"],"steps":["Parboil the taro 2–3 minutes, drain, and rinse away excess surface starch. Blanch the konnyaku briefly and drain.","Combine dashi, shiitake, carrot, bamboo shoots, konnyaku, and taro in a pot. Bring to a gentle simmer and skim carefully so the broth stays clear.","Add chicken or salmon and simmer about 15 minutes until the root vegetables are nearly tender.","Add soy sauce, sake, mirin, salt, and the fish cake. Continue simmering gently until the taro is tender but still holds its shape.","Taste the light broth and adjust seasoning without making it strongly salty.","Finish with blanched snow peas. Serve warm, at room temperature, or chilled depending on season and household tradition."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/988/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten","fish"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Niigata","profile":"Regional home-style","seasonality":"New Year / all year","tags":["Regional home-style","Niigata","New Year / all year"],"photoQueries":["Niigata Noppe のっぺ Japanese food","Niigata Noppe Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_147","title":"Hokkaido Ikameshi","japaneseName":"いかめし","romanization":"ikameshi","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":50,"total":80,"servings":4,"difficulty":"Hard","energy":"normal","cleanup":2,"freezer":"no","equipment":"medium saucepan with lid, toothpicks","ingredients":["4 small whole squid, cleaned, bodies kept intact","120 g Japanese glutinous rice","40 g Japanese short-grain rice","700 ml water","80 ml soy sauce","70 ml sake","60 ml mirin","35 g sugar","20 g ginger, thinly sliced"],"steps":["Rinse both rices together and soak in cool water for 30 minutes, then drain thoroughly.","Check the squid bodies for any remaining cartilage or innards and rinse, then pat dry. Fill each body only about halfway with rice because the grains expand considerably.","Secure each opening with a toothpick and arrange the squid snugly in a saucepan.","Add water, soy sauce, sake, mirin, sugar, and ginger. Bring to a simmer, skim, then cover with a drop lid or parchment lid.","Simmer gently about 40–50 minutes, turning the squid occasionally, until the rice is cooked and the squid is tender. Add a little hot water if the liquid reduces too quickly.","Rest in the cooking liquid for 10 minutes, remove toothpicks, and slice into thick rounds for serving."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/829/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["shellfish","soy","gluten"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Southern Hokkaido","profile":"Regional / niche","seasonality":"All year","tags":["Regional / niche","Southern Hokkaido","All year"],"photoQueries":["Hokkaido Ikameshi いかめし Japanese food","Hokkaido Ikameshi Japanese food"],"auditStatus":"Reviewed 2026"},{"id":"jp_148","title":"Gohei Mochi","japaneseName":"五平餅","romanization":"gohei mochi","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"grill, broiler, or grill pan; skewers","ingredients":["500 g hot cooked Japanese short-grain rice","30 g walnuts","20 g toasted sesame seeds","2 tbsp miso","1 1/2 tbsp soy sauce","2 tbsp sugar","1 tbsp mirin","1–2 tbsp water","4 sturdy flat skewers"],"steps":["While the rice is hot, pound or mash it until roughly half the grains are broken and the mixture becomes sticky enough to hold together.","With damp hands divide into four portions. Press each portion firmly around a flat skewer into an elongated oval about 1.5 cm thick.","Toast walnuts and sesame briefly if needed, then grind them. Mix with miso, soy sauce, sugar, mirin, and enough water to form a thick brushable sauce.","Grill or broil the rice cakes on both sides until the surface dries and begins to brown.","Brush generously with the walnut-miso sauce and grill again briefly until fragrant and lightly caramelized. Watch closely because the sugar can burn.","Serve hot from the grill."],"notes":"A practical researched version. Regional and household variations exist.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed August 2026 against current MAFF regional-cuisine records, Kikkoman Global Cookbook/Washoku guidance, and JNTO food-culture references. Written as practical home-cooking versions; regional and household variations are noted where relevant.","sourceUrls":["https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/448/index.html","https://www.maff.go.jp/e/policies/market/k_ryouri/search_menu/3039/index.html"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","gluten","tree nuts","sesame"],"spiceLevel":"mild","libraryVersion":11,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T09:30:00.000Z","verifiedAt":"2026-08-12","instructionVersion":7,"instructionStyle":"detailed-concise","origin":"Aichi / Gifu / Nagano","profile":"Regional / mountain cuisine","seasonality":"All year","tags":["Regional / mountain cuisine","Aichi / Gifu / Nagano","All year"],"photoQueries":["Gohei Mochi 五平餅 Japanese food","Gohei Mochi Japanese food"],"auditStatus":"Reviewed 2026"}];
